// ══════════════════════════════════════════════════════════════════════
// src/features/smoke/_harness.js — THE SUITE'S FIXTURES, ASSERTIONS AND RUNNERS.
//
// Moved verbatim out of src/features/smoke-test.js: assert/skip, tryRun/tryRunAsync,
// snapshotG/restoreG/sealSnapshot, the fixture factories and the environment probes
// every domain module shares. Nothing here is new — the only edits are the `export`
// keywords and one extra `../` on each specifier, which is what makes one file into
// many. Regenerated by tools/split-smoke-suite.mjs; edit the suite, not this header.
//
// The runner (runSmokeTest) stayed in ../smoke-test.js with the registry, because it
// owns the PLAN and the parks around it, not the fixtures.
// ══════════════════════════════════════════════════════════════════════
import { on, snapshot } from '../../net/events.js?v=552';
import { findUiOverlaps, watchUiOverlaps } from '../ui-overlap.js?v=552';
// b225: the save-conflict rule, lifted out of pullAndMaybeRestore() precisely
// so the "a local save is never discarded silently" promise is provable.
// b226: same reasoning for the auth-event rule — the cached session is what the
// account wall opens on, so "when may we delete it" has to be provable.
import { decideRestore, decideSessionEvent, decideLocalOwnership } from '../../net/auth.js?v=552';
/* BESTIARY CHARMS (CHARM-2). The ladder's magnitudes are READ from the data
   table, never retyped: a designer re-pricing a rung must re-price the
   expectation, not turn the suite red. */
import { CHARM_RANKS } from '../../data/bestiary-charms.js?v=552';

export const errorLog = (window.__errorLog = window.__errorLog || []);

// Capture uncaught errors and unhandled rejections globally so the harness can
// distinguish "test passed" from "test passed but something silently crashed."
const origOnError = window.onerror;
window.onerror = function (msg, src, line, col, err) {
  errorLog.push({ msg: String(msg), src: String(src || ''), line: line || 0, ts: Date.now() });
  if (origOnError) try { origOnError.apply(this, arguments); } catch (e) {}
  return false;
};
window.addEventListener('unhandledrejection', (e) => {
  errorLog.push({ msg: 'unhandled-rejection: ' + (e.reason && e.reason.message || e.reason), ts: Date.now() });
});

// Subscribe to every state event for diagnostic visibility — counts toward the
// runtime-error check at the end of each test run.
on('*', () => {});

/* What a test must not leave behind. Deliberately the SAME patterns
   `closeAllModals()` in legacy.js knows about (it is the game's own census of
   every modal idiom that ever evolved here), plus the one case it cannot see:
   a viewport-covering fixed layer that is not a modal at all — the renown
   celebration scrim, a FTUE step, a dim layer whose owner forgot it.
   Only `body > *` is swept for that case, which is where full-screen layers
   live and is what tests/reachability.mjs sweeps for the same reason; a full
   `body *` walk with getComputedStyle would run 1,300+ times a suite. */
/* PUT EVERY OVERLAY BACK DOWN, through the game's own close paths rather than
   by removing nodes — a test that rips a scrim out of the DOM proves nothing
   about the close button a player has to press, and can leave the owner module
   believing its sheet is still up.
   `closeAllModals()` is the game's own census of the modal idioms; the four
   below are the layers it cannot see, each closed by its owner's published
   close. Call it from a test's finally, never as the last statement of the
   body: a test that throws is exactly the one that leaves the page dirty. */
export function closeOverlays() {
  const t = (fn) => { try { fn(); } catch (e) {} };
  t(() => window.closeAllModals && window.closeAllModals());
  t(() => window.closeQuestsModal && window.closeQuestsModal());
  t(() => window.HearthriseChronicle && window.HearthriseChronicle.close());
  t(() => window.HearthriseDeathSheet && window.HearthriseDeathSheet.close());
  t(() => window.HearthriseAccrual && window.HearthriseAccrual.hideReplacementSheet
    && window.HearthriseAccrual.hideReplacementSheet());
  /* The character picker's own close() is a closure over the overlay it built;
     what it does is drop `.open`, which is what returns the layer to
     `display:none`. Same effect, no node removed. */
  t(() => {
    const ov = document.getElementById('char-select-overlay');
    if (ov) ov.classList.remove('open');
  });
}

/* THE APP SHELL'S SCROLL LOCKS, MEASURED AT BOOT RATHER THAN LISTED BY NAME.
   The brief that produced this asked for "every class that sets overflow hidden
   on html/body/.main/.app, derived from the CSS". Derived, and there are NONE:
   scanned every rule in src/styles/*.css whose SUBJECT is html or body and
   whose body sets `overflow(-x|-y): hidden|clip`, and the only two hits are
   `html{...}` and `body{...}` from one unconditional line —
   legacy.css:24 `html,body{height:100%;overflow:hidden;overscroll-behavior:none}`.
   The app shell is overflow:hidden BY DESIGN, on every viewport, always, with
   no class involved; `hide-profile-overflow` is a profile-strip GRID class
   (legacy.css 2314-2498) that sets no overflow at all and is added
   unconditionally at legacy.js block 23, so it is never residue and never a
   lock. A hard-coded class list would therefore have been an empty list that
   looked like coverage.
   So the lock is measured instead: the four shell boxes' computed overflow is
   captured once before the first test and compared after every test. That
   catches a class, an inline style, an injected stylesheet or a JS-set property
   with one assertion, and it cannot go stale the day a real lock class is
   authored — which a name list would. */
const SHELL_BOXES = ['html', 'body', '.main', '.app'];
const shellLockState = () => SHELL_BOXES.map((sel) => {
  const e = sel === 'html' ? document.documentElement
    : (sel === 'body' ? document.body : document.querySelector(sel));
  if (!e) return sel + ':absent';
  const cs = getComputedStyle(e);
  return sel + ':' + cs.overflowX + '/' + cs.overflowY;
});
let shellLockBaseline = null;
/* Called once by the runner before the first test, so the baseline is the
   APP's authored state and not whatever the first test left. */
export function captureShellLocks() {
  try { shellLockBaseline = shellLockState(); } catch (e) { shellLockBaseline = null; }
  return shellLockBaseline;
}

export function overlayResidue() {
  const out = [];
  const nm = (e) => (e.id ? '#' + e.id : '') + e.tagName.toLowerCase()
    + (typeof e.className === 'string' && e.className ? '.' + e.className.trim().split(/\s+/)[0] : '');
  try {
    /* VISIBLE ones only. Several of these layers are built once and then shown
       and hidden by class — HearthriseDeathSheet.close() drops `.show` and
       leaves #hr-death-scrim in the DOM at display:none, still carrying
       role=dialog. A node that paints nothing covers nothing, and counting it
       would make the correct teardown look like a dirty one. */
    document.querySelectorAll('.modal.show,.modal.open,.ach-overlay.show,.stats-modal.show,'
      + '#quests-modal-overlay,dialog[open],[role=dialog]:not([hidden])')
      .forEach((e) => {
        const cs = getComputedStyle(e);
        if (cs.display === 'none' || cs.visibility === 'hidden' || +cs.opacity < 0.05) return;
        out.push('open overlay ' + nm(e));
      });
    /* An inline lock on a box whose stylesheet already says `hidden` does not
       move the COMPUTED value, so the baseline diff below cannot see it — and
       body is exactly that box here. The two checks are complementary, not
       redundant: this one reads the property the test set, that one reads what
       the page ended up with. `overflow-y` as well as the shorthand, because
       `body.style.overflowY='hidden'` locks the page just as hard and the
       original spelling of this line missed it. */
    for (const [label, e] of [['body', document.body], ['html', document.documentElement]]) {
      const inline = ((e.style.overflow || '') + ' ' + (e.style.overflowY || '')).trim();
      if (/hidden|clip/.test(inline)) out.push(label + ' scroll lock (inline style: ' + inline + ')');
    }
    /* THE SHELL'S OWN LOCKS. A test that leaves html/body/.main/.app with a
       different overflow than the app booted with has taken scrolling away from
       every screen after it — and the bill arrives somewhere else entirely, as
       a control that "cannot be reached" on a surface the test never opened. */
    if (shellLockBaseline) {
      const now = shellLockState();
      for (let i = 0; i < now.length && i < shellLockBaseline.length; i++) {
        if (now[i] === shellLockBaseline[i]) continue;
        out.push('app-shell scroll lock changed — booted with ' + shellLockBaseline[i]
          + ', now ' + now[i] + ' (the shell\'s overflow is authored once in legacy.css; '
          + 'changing it leaves every later screen unable to scroll)');
      }
    }
    document.querySelectorAll('body > *').forEach((e) => {
      if (out.length > 5) return;
      const cs = getComputedStyle(e);
      if (cs.position !== 'fixed' || cs.pointerEvents === 'none') return;
      if (cs.display === 'none' || cs.visibility === 'hidden' || +cs.opacity < 0.05) return;
      const r = e.getBoundingClientRect();
      if (r.width < innerWidth * 0.6 || r.height < innerHeight * 0.5) return;
      out.push('viewport-covering fixed layer ' + nm(e));
    });
  } catch (e) { /* a hygiene detector that throws must never redden a suite */ }
  return out;
}

export const pass = (name) => ({ name, status: 'PASS' });
export const fail = (name, why) => ({ name, status: 'FAIL', why: String(why) });
/* SA-013 (increment 2) — a SKIP is an honest "this seam is not armed yet / this
   environment is not present", DISTINCT from PASS. It is not a passing assertion
   and it does not trip HR_ASSERT_STRICT, but it is counted and printed as
   `N skipped` so an unrun test can never masquerade as a green one — the exact
   confusion the b371 note below calls out ("a skip renders identically to a
   pass"). Declared by skip(reason) from inside a test body; the runner reads the
   module-level flag after the body returns. A FAILING assert throws before any
   skip() can run, so a skip only ever converts a would-be-PASS into an honest
   SKIP — it can never hide a real failure. */
const skipResult = (name, why) => ({ name, status: 'SKIP', why: String(why) });

/* ── SA-013 — ASSERTION COVERAGE INSTRUMENTATION (increment 1, diagnostic) ───
   THE PROBLEM. This runner reports PASS for any test body that does not throw
   and counts NO assertions. So a test that asserts NOTHING — one that
   early-returns before its first `assert`, or was written empty, or is a
   deliberate `assert(true, …)` skip — is indistinguishable in the output from a
   real one. Every "N/N passed / CI green" verdict is only as strong as a runner
   that cannot tell coverage from silence.

   THE FIX (SAFE, TWO INCREMENTS). Increment 1 (this): make `assert` COUNT.
   Every registered test now records how many assertions actually EXECUTED — a
   test that early-returns records the count it reached. runSmokeTest() prints a
   DIAGNOSTIC section at the end (zero-assert PASSes, assert(true) skip sites,
   source-declares-but-runtime-zero). It does NOT change the pass/fail verdict:
   a big-bang red across the skip sites would block CI and force a rushed
   mass-edit. The "fail on zero assertions" behaviour is gated behind
   HR_ASSERT_STRICT, OFF by default. Increment 2 fixes the backlog
   (docs/reports/sa-013-assertion-inventory.md) and flips the flag on.

   WHY A SINGLE MODULE-LEVEL COUNTER IS SAFE. runSmokeTest() awaits each test to
   completion, IN ORDER, before starting the next (never Promise.all — the tests
   mutate the live G). So only one test body is ever executing at a time; the
   runner resets the counter before each body and reads it after. Cost is one
   integer increment per assert. */
let __assertCount = 0;
/* SA-013 (increment 2): the per-test skip flag. Reset alongside __assertCount
   before each body; read by the runner after the body returns. Only one test
   body ever executes at a time (the runner awaits each in order — see the
   module-level counter note above), so a single flag is safe. */
let __skipReason = null;
const withAsserts = (r) => { r.asserts = __assertCount; return r; };

/* SA-013: analyse assertion coverage after a run. results[i] corresponds to
   PLAN[i] — the runner pushes results in iteration order — so we can read the
   EXECUTED count from result.asserts and the SOURCE shape from String(testFn),
   the same source-text technique runSmokeTest already uses for opts.only.

   Categories (a test can be in more than one list):
     · zeroAssertPasses — PASSed but executed ZERO assertions. The core signal.
     · assertTrueSites  — body contains a literal `assert(true …)` skip.
     · earlyReturn      — source declares assert()s but zero executed at runtime
                          (early-return-before-assert). A subset of zeroAssertPasses.
     · throwOnlyPasses  — zero source asserts AND zero executed, but the body
                          contains `throw` — it may verify via a direct throw, so
                          it is NOT automatically "asserts nothing"; flagged for
                          human review, kept OUT of the clean-fix list.
     · assertsNothing   — zero source asserts, zero executed, no throw. The
                          clearest "verifies nothing" case; the fix list. */
export const analyzeAssertionCoverage = (plan, results) => {
  const zeroAssertPasses = [];
  const assertTrueSites = [];
  const earlyReturn = [];
  const throwOnlyPasses = [];
  const assertsNothing = [];
  let totalTrueSkips = 0;
  for (let i = 0; i < results.length; i++) {
    const r = results[i];
    if (!r) continue;
    let src = '';
    try { src = String(plan[i]); } catch (e) { src = ''; }
    const srcAsserts = (src.match(/\bassert\(/g) || []).length;
    const trueSkips = (src.match(/\bassert\(\s*true\b/g) || []).length;
    const executed = r.asserts || 0;
    const throwsOnFail = /\bthrow\b/.test(src);
    if (trueSkips > 0) { assertTrueSites.push({ name: r.name, count: trueSkips }); totalTrueSkips += trueSkips; }
    if (r.status === 'PASS' && executed === 0) {
      const rec = { index: i, name: r.name, srcAsserts, throwsOnFail };
      zeroAssertPasses.push(rec);
      if (srcAsserts > 0) earlyReturn.push(rec);
      else if (throwsOnFail) throwOnlyPasses.push(rec);
      else assertsNothing.push(rec);
    }
  }
  return { zeroAssertPasses, assertTrueSites, earlyReturn, throwOnlyPasses, assertsNothing, totalTrueSkips };
};
/* A SYNC RUNNER HANDED AN ASYNC BODY IS AN ALWAYS-GREEN TEST.
   `tryRun` calls fn() inside a try/catch. Give it an `async` function and it
   receives a PROMISE: nothing throws synchronously, so the catch is unreachable
   and `pass(name)` is returned before a single assertion has run. The test then
   passes whatever it claims, forever, and looks identical to a real one — two
   shipped that way, and seven mutations (including restoring the exact bug) all
   came back green. Detected rather than documented: a thenable return is a LOUD
   failure naming the fix. `tryRunAsync` is the awaiting runner. */
/* ── TEST ISOLATION: THE PENDING-CONSUMPTION LEDGER IS SESSION STATE ────────
   A test that eats (there are a dozen: maybeAutoEat fixtures, eatFood fixtures,
   the auto-eat threshold slider) leaves a HOLD on the live `G` —
   `G._pendingConsume`, the record of "the client spent this and the server has
   not agreed yet" that stops the envelope reconcile restocking eaten food
   (src/net/pending-consume.js). In the GAME that is exactly right and it drains
   on the server's own movement. In the SUITE the next test's envelope is a
   FIXTURE from a different world, and a hold left over from a previous fixture
   subtracts from it — which is how b337 ("the server's answer REPLACES local
   state") started reading `shrimp: 1` for an envelope that says 2.

   So the ledger is cleared at every test boundary. Session scratch is not
   fixture state, and nothing here is asserting the ledger's lifetime — the
   EAT-RESTOCK tests build their own `G` objects or set up inside one test. */
/* ── TEST ISOLATION: A FULL-SCREEN OVERLAY IS NOT ALLOWED TO OUTLIVE ITS TEST ─
   THE CLASS, measured three times now: an eat fixture leaving the
   replacement-gate sheet up, a death sheet raised by an away simulation that had
   not been told it was away, a renown celebration fired by the 4 s watcher off a
   fixture's score. Every instance has the same shape — a modal raised inside
   test A, still on screen in test Z, so the failure lands on Z, hundreds of
   tests away from the fixture that owns it, intermittently, naming an innocent
   surface.

   So the boundary asks. A test that ends with one of these on screen FAILS,
   by name, at its own boundary — and the overlay is taken down, because
   otherwise one leak reds every remaining test in the run and the FIRST report
   is the only true one. This is not a substitute for the teardown: it is what
   makes a missing teardown say so where it happened.

   The list is deliberately short and specific — the dialogs the game raises
   over the whole screen and expects a tap to clear. Anything a test legitimately
   leaves up (a panel, a tab, an inline card) is untouched. */
const OVERLAY_LEAK_SELECTORS = [
  { sel: '#hr-death-scrim.show', what: 'the death sheet (HearthriseDeathSheet.__resetForTest() in your finally)' },
  { sel: '#hr-rn-cele', what: 'the renown rank-up celebration (remove the #hr-rn-cele node in your finally)' },
];
const __overlayLeak = () => {
  try {
    for (const o of OVERLAY_LEAK_SELECTORS) {
      const el = document.querySelector(o.sel);
      if (el) return o;
    }
  } catch (e) {}
  return null;
};
const __clearOverlayLeak = (o) => {
  try {
    if (o.sel === '#hr-death-scrim.show') {
      const D = window.HearthriseDeathSheet;
      if (D && typeof D.__resetForTest === 'function') { D.__resetForTest(); return; }
      if (D && typeof D.close === 'function') { D.close(); return; }
    }
    const el = document.querySelector(o.sel);
    if (el && el.parentNode) el.parentNode.removeChild(el);
  } catch (e) {}
};
/* Returns the ORIGINAL result unless a leak was found, in which case the test
   is failed with the fixture's own name on it. A test that already failed keeps
   its own reason — the leak is a consequence, not the story. */
const withOverlayCheck = (name, r) => {
  const leak = __overlayLeak();
  if (!leak) return r;
  __clearOverlayLeak(leak);
  if (r && r.status === 'FAIL') return r;
  return fail(name, 'OVERLAY LEAK: this test ended with ' + leak.what + ' still on screen. A '
    + 'full-screen overlay that outlives its fixture covers every later test and the failure then '
    + 'lands somewhere else entirely (b483, and twice on b513). Put it away in your finally.');
};
const clearConsumeHolds = () => {
  try {
    const P = window.HearthrisePendingConsume;
    if (P && window.G && typeof P.clearPendingConsume === 'function') P.clearPendingConsume(window.G);
  } catch (e) { /* never let isolation break a run */ }
};

export const tryRun = (name, fn) => {
  clearConsumeHolds();
  __assertCount = 0; // SA-013: reset the per-test assertion counter
  __skipReason = null; // SA-013 (increment 2): reset the per-test skip flag
  try {
    const r = fn();
    if (r && typeof r.then === 'function') {
      return withAsserts(fail(name, 'ASYNC BODY ON A SYNC RUNNER — this test was registered with tryRun(), which cannot '
        + 'await it, so it would report PASS without running a single assertion. Register it with tryRunAsync().'));
    }
    if (__skipReason !== null) return withAsserts(skipResult(name, __skipReason));
    return withAsserts(withOverlayCheck(name, pass(name)));
  } catch (e) { return withAsserts(withOverlayCheck(name, fail(name, e && (e.message || e)))); }
  finally { clearConsumeHolds(); }
};
/* b337 — THE SUITE CAN NOW AWAIT.
   Until now every test was synchronous, which meant a network path could only
   ever be asserted at the moment the request was DISPATCHED — never on what
   came back. That is exactly the shape this repo's "assertions that assert
   nothing" family keeps taking: the half of the path you can reach becomes the
   whole of what you claim. tests/run-smoke.mjs has always done
   `await Promise.race([Promise.resolve(window.__smokeTest(...)), …])`, so the
   harness could already handle a promise; only the in-page runner could not.
   runSmokeTest() below now awaits each entry IN ORDER — order is load-bearing,
   because these tests mutate the live G. */
export const tryRunAsync = (name, fn) => Promise.resolve()
  // SA-013: reset the counter + skip flag and call fn() in the SAME microtask,
  // so nothing can slip an assert between the reset and the body.
  .then(() => { clearConsumeHolds(); __assertCount = 0; __skipReason = null; return fn(); })
  .then(() => { clearConsumeHolds(); return withAsserts(__skipReason !== null ? skipResult(name, __skipReason) : withOverlayCheck(name, pass(name))); },
        (e) => { clearConsumeHolds(); return withAsserts(withOverlayCheck(name, fail(name, e && (e.message || e)))); });
/* SA-013: count every assertion that EXECUTES (increment before the check, so a
   throwing assert is still counted as "reached"). The counter is reset by the
   runner before each test body. Cost: one increment per call. */
export const assert = (cond, msg) => { __assertCount++; if (!cond) throw new Error(msg); };
/* SA-013 (increment 2): declare an honest SKIP for a seam that is not armed in
   this build, or an environment that is not present in this run (mobile-only on a
   desktop viewport, https-only over http, live-config-only offline, an empty
   fresh-account fixture). It records a reason and returns control to the body
   (callers pair it with `return`). It is NOT an assertion — it does not count
   toward coverage — and the runner reports it as SKIPPED, never as a passing
   test. Never use skip() to silence a failing real assertion: a skip means "this
   was not run", not "this was checked". */
export const skip = (reason) => { __skipReason = String(reason == null ? '' : reason); };

/* Shared rig for the bounty-envelope battery: one target, one save/restore of
   bountyHunter, one GoalClaim stub that LOGS its calls and HOLDS the claim, one
   envelope builder. `credit` is overridable; the claim is always held, so no
   test built on this can reach finalizeBounty's celebration path. */
export function bountyRig(opts) {
  const G = window.G, o = opts || {};
  const savedBh = JSON.parse(JSON.stringify(G.bountyHunter || {}));
  const savedGC = window.HearthriseGoalClaim;
  const calls = [];
  window.HearthriseGoalClaim = Object.assign({}, savedGC, {
    isSignedIn: () => true,
    creditKills: (t, c) => { calls.push({ fn: 'credit', claimed: c }); return Promise.resolve(o.credit || { ok: false, error: 'held' }); },
    claimBounty: () => { calls.push({ fn: 'claim' }); return Promise.resolve({ ok: false, error: 'held' }); },
  });
  const target = (window.MONSTERS && window.MONSTERS.goblin) ? 'goblin' : Object.keys(window.MONSTERS || {})[0];
  return {
    calls, target,
    armed: typeof window.clientMayWriteRecordField === 'function' && window.clientMayWriteRecordField('gold') === false,
    set(b) { if (window.ensureBountyState) window.ensureBountyState(); G.bountyHunter.active = b; return b; },
    // hr_state_of's shape: the contract plus greatest(0, kills - baseline).
    envelope(id, progress) {
      const a = G.bountyHunter.active || {};
      return { state: { bounty: { bounty_id: id, target, required: a.required, baseline: 100,
        kills_now: 100 + progress, progress } } };
    },
    restore() {
      window.HearthriseGoalClaim = savedGC;
      const ab = G.bountyHunter && G.bountyHunter.active;
      if (ab && window.hrClearBountyRetry) { try { window.hrClearBountyRetry(ab); } catch (e) {} }
      G.bountyHunter = savedBh;
    },
  };
}
/* SA-013 (increment 2): a "this must not throw" contract, as a COUNTED
   assertion. The interactive tests used to wrap each call in try/catch and
   re-throw — a guard that only ran (and only counted) when the call actually
   threw, so on the happy path the test asserted nothing and reported a silent
   green. callOk asserts on EVERY call, so "clicking/invoking X does not throw"
   becomes real, counted coverage. clickOk is the same contract for a DOM click. */
export const callOk = (label, fn) => {
  let err = null;
  try { fn(); } catch (e) { err = e; }
  assert(!err, label + ' threw: ' + (err && (err.message || err)));
};
export const clickOk = (el, label) => callOk(label, () => el.click());

/* R4 COOKING PAUSE — run a cooking-MECHANIC regression under a TEMPORARY arm.
   Cooking is disarmed (paused) in this build, so the live cooking loop (start,
   produce, burn, counters, tile) is gated off. The historical cooking regression
   tests below still guard that loop — the code path that MUST keep working for
   the day the server owns noBurn and cooking is re-armed — so they run with the
   arm flipped ON via the same seam the accrual engine reads, and ALWAYS revert to
   the disarmed default in finally (even on throw / async rejection), so the
   dedicated pause guards (B431-4, R4-COOKING-PAUSE, B385, OFFLINE-CLARITY 2) still
   see cooking paused. Handles sync and thenable-returning test bodies. */
export const withCookingArmed = (fn) => {
  const AS = (window.HearthriseCore && window.HearthriseCore.artisanSim) || null;
  const arm = (v) => { if (AS && typeof AS.__setCookingSettlementArm === 'function') AS.__setCookingSettlementArm(v); };
  arm(true);
  let r;
  try { r = fn(); }
  catch (e) { arm(null); throw e; }
  if (r && typeof r.then === 'function') return r.then((v) => { arm(null); return v; }, (e) => { arm(null); throw e; });
  arm(null);
  return r;
};

/* ── stampBalanceLikeLoad — THE MISSING HALF OF THE HARNESS (gold-arm) ────────
   THE PROBLEM THIS SOLVES, STATED EXACTLY. When gold/gems are ARMED into
   SERVER_OF_RECORD, `balanceOf` no longer trusts the presence of a number in G —
   it trusts `G._record`, the provenance stamp that ONLY `applyRecord` writes (the
   b347 fingerprint rule). In production `hr_load` stamps that record before the
   first render, so `G.gold` reads KNOWN. The smoke harness never runs a real
   `hr_load`, so a test that does `G.gold = N` leaves the balance UNKNOWN and
   every affordability-gated action fail-closes — ~48 economy/UI tests go red not
   because the code regressed but because the test never simulated the load.

   This is that simulation, and it is FAITHFUL by construction: it goes through
   the REAL `window.HearthriseRecord.applyRecord` with a properly-shaped server
   envelope carrying `state.gold`/`state.gems` = the current `G.gold`/`G.gems` —
   exactly the bytes `hr_load`/`applyServerEnvelope` (legacy.js:1956) route
   through applyRecord. It POKES NO `_record` internals: a green suite therefore
   proves the armed READ path (decodeRecord → applyRecord → recordValue →
   balanceOf) actually works, rather than faking the stamp.

   ⚠ IT IS OPT-IN, PER TEST, and deliberately not a tryRun-level auto-stamp. A
     blanket stamp would hide a real regression in which production forgot to
     re-stamp after a server write — the exact `client-overwrote` fault b347/b356
     exist to catch. A test calls this only when it legitimately HAS a loaded
     balance (it set one and expects a purchase to work, or it simulated a load).
     A test that verifies fail-closed/UNKNOWN on a genuinely-unstamped balance
     must NOT call it.

   It mirrors hr_load by supplying EVERY armed field it can (gold, gems, and the
   `accrued_to` watermark from G.offlineBudget.at when present) so applyRecord's
   wholesale `_record` replacement never silently drops a field the test still
   relies on. Monotonic-version-safe: it clears any prior stamp. */
export function stampBalanceLikeLoad(G, opts) {
  const o = opts || {};
  const R = (typeof window !== 'undefined') && window.HearthriseRecord;
  if (!R || !G || typeof G !== 'object') return null;
  const armed = R.serverOfRecordFields();
  const state = {};
  if (armed.indexOf('gold') !== -1 && typeof G.gold !== 'undefined') state.gold = G.gold;
  if (armed.indexOf('gems') !== -1 && typeof G.gems !== 'undefined') state.gems = G.gems;
  /* Preserve the watermark: applyRecord REPLACES G._record wholesale, so if a
     prior stamp had offlineBudget KNOWN and we omit accrued_to, it would drop off
     the `known` list. Re-supply it from the value the client already holds. */
  if (armed.indexOf('offlineBudget') !== -1) {
    const at = G.offlineBudget && Number(G.offlineBudget.at);
    if (Number.isFinite(at) && at > 0) state.accrued_to = at;
  }
  const prev = (G._record && Number(G._record.version)) || 0;
  const version = Number.isFinite(o.version) ? o.version : Math.max(prev + 1, Date.now());
  return R.applyRecord(G, { ok: true, version, now: new Date(version).toISOString(), state });
}

/* ── stampRecordLikeLoad — THE SAME HARNESS FOR **EVERY** ARMED FIELD ─────────
   b456 TEST-DEBT BURN-DOWN. `stampBalanceLikeLoad` above solved this problem for
   gold/gems when those two armed. The b454 cutover armed SEVEN more fields
   (skills, equipment, rooms, marks, restedXp, restedAt, alongside offlineBudget),
   and every one of them landed the suite in the identical hole its header
   describes: the harness never runs a real `hr_load`, so `G._record` is absent,
   so `roomsOf`/`marksOf`/`skillXpOf`/`equipmentMap`/`restedOf` all fail-closed to
   UNKNOWN — and ~40 tests that legitimately DO have a loaded character went red
   without a single line of product code having regressed.

   This is that simulation for the whole envelope, and it is FAITHFUL in exactly
   the way the gold one is: it POKES NO `_record` INTERNALS. It builds a properly
   shaped hr_load envelope out of what G currently holds and pushes it through the
   REAL `window.HearthriseRecord.applyRecord`, so a passing test proves the armed
   READ path (pick/decode → applyRecord → recordValue → the per-field accessor)
   actually carries the value. Each field is placed where hr_state_of really puts
   it, which is three different places and is the reason this cannot be one loop:
     • `state.{gold,gems,marks,rested_xp,rested_at,accrued_to}` — flat scalars;
     • `res.skills` / `res.equipment` — TOP-LEVEL siblings of `state`;
     • `res.progress[]` — `{kind:'unlock', key:'room:<id>', value:<rung>}` rows,
       which `pickRooms` shapes into the `{id: rung}` map.

   ⚠ IT IS OPT-IN, PER TEST, for the reason stampBalanceLikeLoad states and which
     applies with more force now: a blanket stamp would hide a real regression in
     which production forgot to re-stamp after a server write (the b347/b356
     `client-overwrote` fault). A test that verifies fail-closed/UNKNOWN behaviour
     on a genuinely-unstamped field must NOT call it.

   ⚠ IT ONLY EVER STAMPS FIELDS THAT ARE CURRENTLY ARMED (serverOfRecordFields()),
     so it is a no-op for a dormant field and safe to call from a test that has
     forced a seam off.

   ⚠ IT NEVER INVENTS A VALUE. A field G does not hold — or holds in a shape the
     server's decoder would reject — is simply not supplied, which leaves it
     UNKNOWN exactly as a lean envelope would. The return value is applyRecord's
     report, so a caller can assert `written` contains what it needed.

   ⚠ STAMP **BEFORE** THE ACTION YOU ARE MEASURING, not after. applyRecord retires
     the display predictions the envelope's watermark covers — faithfully, because
     a real hr_load carrying a fresh `accrued_to` genuinely does contain them — so
     stamping in the middle of a measurement can legitimately erase the very grant
     the test just made. Set the world up, stamp, then act, then read. */
export function stampRecordLikeLoad(G, opts) {
  const o = opts || {};
  const R = (typeof window !== 'undefined') && window.HearthriseRecord;
  if (!R || !G || typeof G !== 'object') return null;
  const armed = R.serverOfRecordFields();
  const has = (f) => armed.indexOf(f) !== -1;
  const state = {};
  const res = { ok: true };

  if (has('gold') && typeof G.gold !== 'undefined') state.gold = G.gold;
  if (has('gems') && typeof G.gems !== 'undefined') state.gems = G.gems;
  if (has('marks')) { const n = Number(G.marks); if (Number.isFinite(n) && n >= 0) state.marks = Math.floor(n); }
  if (has('restedXp')) { const n = Number(G.restedXp); if (Number.isFinite(n) && n >= 0) state.rested_xp = Math.floor(n); }
  /* Both watermarks decode with the "act only on CERTAINTY" rule — a zero/negative
     epoch is not a watermark — so an absent or garbage one is left UNKNOWN here
     rather than being invented as 1970, which is what the decoder would refuse. */
  if (has('restedAt')) { const n = Number(G.restedAt); if (Number.isFinite(n) && n > 0) state.rested_at = Math.floor(n); }
  if (has('offlineBudget')) {
    const at = G.offlineBudget && Number(G.offlineBudget.at);
    if (Number.isFinite(at) && at > 0) state.accrued_to = at;
  }
  if (has('skills') && G.skills && typeof G.skills === 'object' && !Array.isArray(G.skills)) {
    /* decodeSkills condemns the WHOLE map on one bad cell and treats an EMPTY map
       as "the read did not populate", so mirror both rules rather than shipping a
       map the decoder will reject: drop non-finite cells, and supply nothing at
       all when the result is empty. */
    const m = {}; let n = 0;
    for (const k in G.skills) {
      if (!Object.prototype.hasOwnProperty.call(G.skills, k)) continue;
      const v = Number(G.skills[k]);
      if (Number.isFinite(v) && v >= 0) { m[k] = Math.floor(v); n++; }
    }
    if (n) res.skills = m;
  }
  if (has('equipment') && G.equipment && typeof G.equipment === 'object' && !Array.isArray(G.equipment)) {
    /* The wire carries `{slot: item_id}` with `null` for an explicit empty slot.
       An id the server's grammar would reject is passed through UNCHANGED so the
       decoder condemns the set exactly as it would in production — silently
       dropping it here would make the harness kinder than the server. */
    const m = {};
    for (const k in G.equipment) {
      if (!Object.prototype.hasOwnProperty.call(G.equipment, k)) continue;
      const v = G.equipment[k];
      m[k] = (typeof v === 'string' && v) ? v : null;
    }
    res.equipment = m;
  }
  if (has('rooms')) {
    const prog = [];
    const rooms = (G.rooms && typeof G.rooms === 'object' && !Array.isArray(G.rooms)) ? G.rooms : {};
    for (const k in rooms) {
      if (!Object.prototype.hasOwnProperty.call(rooms, k)) continue;
      const v = Number(rooms[k]);
      if (Number.isFinite(v) && v >= 0) prog.push({ kind: 'unlock', key: 'room:' + k, value: Math.floor(v), period: '' });
    }
    res.progress = prog;   // a PRESENT-but-empty progress array is "owns no rooms", not UNKNOWN
  }
  const prev = (G._record && Number(G._record.version)) || 0;
  res.version = Number.isFinite(o.version) ? o.version : Math.max(prev + 1, Date.now());
  res.now = new Date(res.version).toISOString();
  res.state = state;
  return R.applyRecord(G, res);
}

/* ══════════════════════════════════════════════════════════════════════════
   b456 — DRIVING THE LOCAL SAVE BLOB, WHICH IS NOW THE **OFF** POSITION.
   ══════════════════════════════════════════════════════════════════════════
   The b455 capstone RETIRES the local blob: with `BLOB_RETIRED` armed (the
   shipped default) `saveLocal()` returns before it writes and `loadLocal()`
   returns before it reads, dropping any leftover blob on the way past. That is
   correct — the live cutover proved a local blob is not a cache but a STALE
   RIVAL that resurrected dead state on every boot — and it silently turned every
   save/load round-trip test in this file into a test of nothing. Nine of them
   went red in one run; the dangerous ones were the two that stayed GREEN.

   The wrong fix is to delete them. `saveLocal`/`loadLocal` still SHIP, behind
   the capstone flag, and this file's own recurring lesson applies: a kill switch
   whose off position is untested is not a kill switch. The parked-save policy
   (b318), the slot-mismatch park (b372), the account-wall gate (b224) and the
   strip-at-the-caller seam (B340-3) all live in that code and all still matter
   the moment the flag is turned back.

   So a save/load test runs in the position it is ABOUT — blob live, pinned per
   test, restored to PRISTINE (which is RETIRED) afterwards. The ARMED contract
   is asserted separately and once, by CAPSTONE-NOOP below, so "the blob is
   retired" is a property with a test rather than an ambient reason things pass.

   ⚠ A TEST WRAPPED HERE DOES **NOT** COVER THE SHIPPING DEFAULT. */
const pinLocalBlob = () => {
  const C = window.HearthriseCapstone;
  if (!C || typeof C.__setBlobRetired !== 'function') return null;
  C.__setBlobRetired(false);
  return C;
};
const unpinLocalBlob = (C) => {
  if (!C) return;
  try { C.__setBlobRetired(null); } catch (e) {}
};
/** Run `fn` with the local save blob LIVE (capstone disarmed), restoring after. */
export const withLocalBlob = (fn) => {
  const C = pinLocalBlob();
  try { return fn(); } finally { unpinLocalBlob(C); }
};
/** The awaiting twin, for tryRunAsync bodies. */
const withLocalBlobAsync = async (fn) => {
  const C = pinLocalBlob();
  try { return await fn(); } finally { unpinLocalBlob(C); }
};

/* ── 2026-09-08 — THE SAME PROBLEM FOR THE HERO-SLOT ENTITLEMENT ─────────────
   `hr_buy_hero_slot` moved hero-slot ownership to the server: hr_state_of
   projects the account's owned set, src/net/accrue.js reconcileHeroSlots lands
   it in `G._heroSlots`, and multi-character.js `ownsSlot`/`unlockedCount` prefer
   it over the `G.heroSlotsUnlocked` residue — which is the whole fix, because
   the residue is the store a cloud restore can rewind while the entitlement it
   paid for stays granted (the b371 dupe).

   Four tests below are ABOUT the CLIENT-OWNED path (`unlockSlot`, kept verbatim
   as the pre-arm branch and unreachable from any UI once gems are armed). Signed
   in against a server that carries the projection, `G._heroSlots` is populated,
   so those tests would be asserting the residue against a server answer that
   correctly disagrees with it — a green-today, red-on-apply trap, which is worse
   than a failure. So they run in the position they are ABOUT: server answer
   ABSENT, residue authoritative, restored afterwards.

   ⚠ A TEST WRAPPED HERE DOES **NOT** COVER THE ARMED PATH. That is SLOT-SRV-*,
   which drives the server verb and asserts the residue is NOT believed. */
export const withClientOwnedSlots = (fn) => {
  const G = window.G;
  const had = !!(G && Object.prototype.hasOwnProperty.call(G, '_heroSlots'));
  const prev = had ? G._heroSlots : undefined;
  /* AND IT HAS TO SAY WHO OWNS THE GEMS, which is what "client-owned" means:
     residueCount() now fails safe to slot 0 unless `clientMayWriteRecordField
     ('gems')` is TRUE, because "no projection AND the server owns the gems" is
     the boot state a stale residue was opening slots in — the defect itself, not
     a state to test in. Other fields pass through (a blanket `() => true` would
     hand four unrelated subsystems a client writer). */
  const origMay = window.clientMayWriteRecordField;
  try {
    if (G) delete G._heroSlots;
    window.clientMayWriteRecordField = (f) => (f === 'gems' ? true
      : (typeof origMay === 'function' ? origMay(f) : true));
  } catch (e) {}
  try { return fn(); } finally {
    window.clientMayWriteRecordField = origMay;
    try { if (G) { if (had) G._heroSlots = prev; else delete G._heroSlots; } } catch (e) {}
  }
};

/* ── b514 (cleanup slice 4) — THE FARM IS DRIVEN AGAINST A STUBBED SERVER ────
   b456 tested the farm by turning the SERVER ROUTING OFF (`withLocalFarm`) and
   measuring the client-authored twin underneath. That twin is now DELETED —
   plantCrop / waterPlot / waterAllPlots / harvestPlot / upgradePlot send an
   hr_farm_* intent and author nothing (tests/no-client-farm-mint.mjs is the
   standing guard) — so a harness that disarms the routing would measure code
   that does not exist. Worse, it was never testing the shipping path.

   What replaces it tests MORE, not less: `withFarmServer` swaps the four
   transport methods on `window.HearthriseFarmSync` for recorders that answer
   with a canned SERVER ENVELOPE, and leaves `reconcileFarmResult` REAL. Each
   test therefore proves the two halves the client actually owns now:
     · the GESTURE became the right intent (or was refused by the pre-flight
       without one — a refusal that still calls the server is a bug), and
     · the RESPONSE was rendered exactly once, with the server's numbers.
   The RULES themselves (the yield roll, the watering window, the perennial
   ladder, gold-before-deeds) are hr_farm_*'s and are proven by the §10 self-check
   in 2026-08-22-server-farming-complete.sql + 2026-09-06-plot-tier-reachable.sql.

   ⚠ THE STUB'S `then` IS SYNCHRONOUS ON PURPOSE. The call sites are
   `FS.farmX(...).then(cb)`; a real Promise would defer `cb` to a microtask and
   every assertion below would run before the reconcile. A thenable that calls
   back inline keeps these tests synchronous without changing what they read. */
export const withFarmServer = (respond, fn) => {
  const F = window.HearthriseFarmSync;
  if (!F) return undefined;   // module absent ⇒ nothing to drive; the guard covers the source
  const VERBS = ['farmPlant', 'farmWater', 'farmHarvest', 'farmUpgradePlot'];
  const saved = {};
  const calls = [];
  const inline = (res) => ({ then(cb) { cb(res); return this; } });
  for (const v of VERBS) {
    saved[v] = F[v];
    F[v] = function (...args) { calls.push({ verb: v, args }); return inline(respond(v, args, calls)); };
  }
  /* ⚠ `G._serverPlotLevel` LEAKS PAST restoreG AND THE HARNESS MUST CONTAIN IT.
     reconcileFarmResult writes BOTH `G.plotLevels` and the `_`-prefixed mirror
     (src/net/farm-sync.js), and `_` fields are scratch by design — snapshotG
     does not carry them, so a tier this harness hands the client would otherwise
     stay authoritative for every later test (getPlotLevel() prefers the mirror
     and rewrites plotLevels from it). That is a HARNESS artifact, not a product
     one: in a real session the mirror IS the server's tier and outliving a
     reload is the point. Saved and restored here, beside the transport it
     travels with, so no test has to remember. */
  const G = window.G || {};
  const hadMirror = Object.prototype.hasOwnProperty.call(G, '_serverPlotLevel');
  const prevMirror = G._serverPlotLevel;
  try { return fn(calls); } finally {
    for (const v of VERBS) F[v] = saved[v];
    try { if (hadMirror) G._serverPlotLevel = prevMirror; else delete G._serverPlotLevel; } catch (e) {}
  }
};

/* The farm state the replant/sweep tests share: a property with room to farm, a
   SERVER plot tier of 2, a farmer who has out-levelled every gate, one ready
   turnip in plot 0, and a bag holding ONLY the seeds the test names (enumerated
   from the catalogue, so a new crop cannot leak into a sweep's budget). */
export const farmReplantFixtureG = (seeds) => {
  const G = window.G;
  G.homestead = { tier: 5 };
  G._serverPlotLevel = 2; G.plotLevels = 2;
  G.skills.farming = 1000000;
  G.inventory = Object.assign({}, G.inventory);
  Object.values(window.CROPS || {}).forEach((c) => { delete G.inventory[c.seed]; });
  Object.assign(G.inventory, seeds || {});
  /* The gate counts what the SERVER holds (accrue.js gateItemCount), so a fixture
     that wants its gesture SENT states a server bag: here the server agrees with
     the bag, and the tier/level gates are what the test is about. */
  G._serverBag = Object.assign({}, G.inventory);
  G.farmPlots = [{ cropId: 'turnip', plantedAt: Date.now() - 9e7, waterings: [], state: 'ready' }];
};
/* One envelope shape for both: harvest clears the plot, any plant is accepted. */
export const farmHarvestThenPlant = (verb, args) => (verb === 'farmHarvest'
  ? { ok: true, plot: args[0], crop: 'turnip', produce: 'turnip', qty: 3, xp: 30, regrew: false, withered: false }
  : { ok: true, plot: args[0], crop: args[1], planted_at: new Date().toISOString(),
      seed_spent: args[1] + '_seed', plant_xp: 28 });

/* ── withDeferredFarmPlant — THE SERVER ANSWERS LATER, WHICH IS THE POINT ─────
   withFarmServer's thenable calls back INLINE, so a reconcile (and the server's
   seed debit) has already landed before the caller's next statement. That hides
   every defect that lives in the window between an intent and its answer — the
   "Plant all" sweep that re-read the bag and funded one intent per plot off a
   single seed did the right thing under an inline fixture and the wrong thing in
   a browser. This records plant intents and HOLDS their answers until the test
   asks for them. Written once, here, beside the fixture it corrects. */
export const withDeferredFarmPlant = (fn) => {
  const F = window.HearthriseFarmSync;
  if (!F) return undefined;
  const saved = F.farmPlant;
  const calls = [];
  const pending = [];
  F.farmPlant = function (plotIdx, cropId) {
    calls.push({ plot: plotIdx, crop: cropId });
    return { then(cb) {
      pending.push(() => cb({ ok: true, plot: plotIdx, crop: cropId, planted_at: new Date().toISOString(),
        seed_spent: cropId + '_seed', plant_xp: 28 }));
      return this;
    } };
  };
  try { return fn(calls, () => { while (pending.length) pending.shift()(); }); }
  finally { F.farmPlant = saved; }
};


/* ==========================================================================
   b515 - withServerBacked: THE ONE FIXTURE FOR "THE SERVER OWNS THE OUTCOME".
   ==========================================================================
   WHAT IT REPLACES, AND WHY THE THING IT REPLACES WAS NEVER A TEST OF THE GAME.
   Twenty-six gameplay tests in this file ran under `tryRunClientAuthoritative`,
   which turned the b353 kill switch OFF for the duration. Off, `isRecordActive()`
   was false, so `clientMayWriteRecordField()` answered TRUE for every field and
   the client authored its own gold, gems, marks, skills and room rungs. Those
   tests therefore measured a pre-cutover client that has not shipped since b454
   and no longer exists at all: the switch is retired (b515) and the OFF branches
   are deleted. Every one of them went red in the same run, and the honest
   reading of that red is not "the suite broke" - it is "these tests were never
   watching the shipping game".

   THE SHIPPING GAME, stated exactly, because the fixture has to be shaped like
   it (src/net/gold.js `sendGoldIntent` -> `settleVerdict`):

     gesture -> buildGoldRequest -> fetch(hr-accrue) -> the answer body carries
     an ENVELOPE -> the `onEnvelope` hook (the REAL applier, wired by legacy.js)
     -> `G.gold` / `G.gems` / the record are written ABSOLUTELY from the SERVER's
     numbers -> the local prediction is retired.

   So the fixture stubs exactly ONE thing - `window.fetch` - and leaves every
   other link real: the request builder, the intent key, the classifier, the
   envelope reader, the applier, the prediction ledger. A test written on it
   proves the two halves the client actually owns now (the gesture became the
   right INTENT, and the SERVER's answer was applied once) and cannot pass by
   the client having authored the number, because the client cannot.

   THE DRAIN IS NOT OPTIONAL AND A MICROTASK DRAIN IS NOT ENOUGH. `res.json()`
     resolves on a TASK. B354-1 learned this the hard way: eighty
     `await Promise.resolve()`s asserted on a balance the envelope had not
     reached and reported the double-pay window as OPEN when it was closed. Use
     `await rig.drain()` after any gesture and before any assertion.

   IT IS NOT A LICENCE TO ASSERT A CLIENT NUMBER. The envelope this fixture
     answers with is the SERVER's, and a test must assert the server's value
     landed - never that the client's arithmetic did. `grant` is deliberately an
     ABSOLUTE state, not a delta, for that reason: a test that wants "+50 gold"
     has to state the total it expects the server to have reached, which is the
     only thing the player will ever see.

   rig = {
     sent,                  every intent body that reached the wire, in order
     drain(),               await this before asserting (see above)
     grant(state, extra),   set the NEXT answer's `state` overrides / body extras
     reply(fn),             full control: (body, url) => Response | body | null
     envelope(state, extra) build one by hand (for a test that applies its own)
   }
   `opts.state` seeds the answer's state for every call; `opts.urlRe` (default
   /hr-accrue/) selects which requests are intercepted - anything else falls
   through to the real fetch, so an icon or a stylesheet still loads. */
export const withServerBacked = (opts, fn) => {
  const o = opts || {};
  const G = window.G;
  const Gd = window.HearthriseGold;
  const urlRe = o.urlRe || /hr-accrue/;
  const realFetch = window.fetch;
  const hadGoldCfg = (Gd && typeof Gd.getGoldConfig === 'function') ? Gd.getGoldConfig() : null;
  const sent = [];
  /* ⚠ NEWER THAN WHATEVER IS ALREADY STAMPED. `applyRecord` is MONOTONIC on
     `version` and only fills GAPS from an older envelope — so a fixture that
     stamped a known value (a room rung, a balance) with `stampRecordLikeLoad`,
     which uses `Date.now()`, would silently refuse every answer this rig gives
     if the rig started counting from a small number. Measured: the room-rung
     assertion in b227's property-gate test failed for exactly this and for no
     other reason. */
  let version = Math.max(((G && G._record && Number(G._record.version)) || 0) + 1, Date.now());
  let nextState = null;
  let nextExtra = null;
  let replyFn = null;

  /* The answer body. `state`, `skills` and `inventory` are all REQUIRED by
     src/net/gold.js `envelopeOf` - a body missing any of them is not an
     envelope, is not applied, and would make every assertion below measure the
     ABANDONED branch instead of the applied one. Built from what G holds now so
     the fixture never silently rewrites a field the test did not name. */
  const envelope = (state, extra) => {
    const skills = {};
    for (const k of Object.keys(G.skills || {})) skills[k] = { xp: G.skills[k] };
    return Object.assign({
      ok: true,
      version: ++version,
      now: new Date().toISOString(),
      state: Object.assign(
        { gold: G.gold, gems: G.gems, active_kind: 'idle', active_id: null, accrued_to: null },
        o.state, state
      ),
      skills,
      inventory: Object.assign({}, G.inventory),
    }, o.extra, extra);
  };

  const rig = {
    sent,
    envelope,
    drain: async () => { for (let i = 0; i < 12; i++) await new Promise((r) => setTimeout(r, 0)); },
    grant: (state, extra) => { nextState = state || null; nextExtra = extra || null; return rig; },
    reply: (f) => { replyFn = f; return rig; },
  };

  window.fetch = function (u, init) {
    const url = String(u);
    if (!urlRe.test(url)) return realFetch.apply(this, arguments);
    let body = null;
    try { body = JSON.parse((init && init.body) || 'null'); } catch (e) { body = null; }
    sent.push(body);
    if (replyFn) {
      const custom = replyFn(body, url, sent);
      if (custom) {
        return Promise.resolve(custom instanceof Response
          ? custom : new Response(JSON.stringify(custom), { status: 200 }));
      }
    }
    return Promise.resolve(new Response(JSON.stringify(envelope(nextState, nextExtra)), { status: 200 }));
  };
  if (Gd && typeof Gd.configureGold === 'function') {
    Gd.resetGold();
    Gd.configureGold({ url: 'https://probe.supabase.co', apiKey: 'anon', authToken: () => 'jwt' });
  }
  /* ── THE TWO GATES A REAL SESSION HAS ALREADY PASSED ──────────────────────
     `applyGoldEnvelope` refuses to write for two reasons that have nothing to
     do with the gesture under test, and BOTH are true of this harness and of no
     real player:

       · isReconcilePending() — the b314 snapshot hold. It is held until the
         cloud reconcile settles, which never happens here because there is no
         cloud. Held, every verb envelope is DEFERRED and applies nothing.
       · isReplacementAcknowledged() — the b366 first-contact consent. Any
         envelope whose gold is LOWER than G's reads `destructive` on plain
         arithmetic, and a purchase always lowers gold, so an unacknowledged
         client refuses its own successful purchase.

     Both are released for the duration and restored exactly as found, which is
     the same pair B354-1 and the b371 sync tests already manage by hand. A test
     ABOUT either gate must not use this fixture — `ACCRUE-REPLACE-HANDOFF` owns
     the deferral and drives it directly. */
  const A = window.HearthriseAccrual;
  const Sy = window.HearthriseSync;
  const wasAck = A ? A.isReplacementAcknowledged() : null;
  const wasHeld = (Sy && typeof Sy.isSnapshotHeld === 'function') ? Sy.isSnapshotHeld() : null;
  if (A) A.acknowledgeReplacement(true);
  if (wasHeld === true) Sy.releaseSnapshots();

  const restore = () => {
    window.fetch = realFetch;
    if (Gd && typeof Gd.configureGold === 'function') { Gd.resetGold(); Gd.configureGold(hadGoldCfg || null); }
    if (A && wasAck !== null) A.acknowledgeReplacement(wasAck);
    if (wasHeld === true) Sy.holdSnapshots();
  };
  let r;
  try { r = fn(rig); } catch (e) { restore(); throw e; }
  if (r && typeof r.then === 'function') {
    return r.then((v) => { restore(); return v; }, (e) => { restore(); throw e; });
  }
  restore();
  return r;
};

/* -- withRoomServer - THE ROOM RUNG COMES BACK ON THE ANSWER (b515) ---------
   `upgradeRoom` / `upgradeProperty` are `hr_unlock_buy` gestures: the offer id
   is `room.<id>.<rung>` (or `property.<tierId>`), NO price crosses, and the rung
   advances ONLY on the server's ok — `clientMayWriteRecordField('rooms')` is
   false, so the local `G.rooms[id] = lv+1` is skipped and the rung arrives on
   the envelope as a `progress` row that `record.js pickRooms` shapes into the
   map. Anything that asserts "the room is built" therefore has to let the
   server say so.

   This wraps `withServerBacked` with the two things a room purchase needs: the
   `progress` rows for what is now owned, and the SERVER's post-purchase gold
   (deliberately a number the client did not compute, so a test cannot pass by
   the client having debited). The gesture is async — `buyUnlock` resolves with
   the verdict — so `await rig.drain()` before reading anything.

   `owned` is `{roomId: rung}` and/or `{'property:<tierId>': 1}`; `gold` is the
   absolute balance the server is left holding. */
export const withRoomServer = (owned, gold, fn) => {
  const progress = [];
  for (const k of Object.keys(owned || {})) {
    progress.push(k.indexOf(':') >= 0
      ? { kind: 'unlock', key: k, value: Number(owned[k]) || 1, period: '' }
      : { kind: 'unlock', key: 'room:' + k, value: Number(owned[k]) || 1, period: '' });
  }
  return withServerBacked({
    state: (typeof gold === 'number') ? { gold: gold } : undefined,
    extra: { progress },
  }, fn);
};

/* -- withClaimServer - A CLAIM IS A ROUND TRIP, AND THE REWARD IS NOT LOCAL --
   Every period reward in the game — a Collection milestone, a Renown rank, a
   daily login, a quest — pays in gold / gems / skill XP / items, and every one
   of those four is SERVER-OF-RECORD and armed. So each claim site makes the
   SAME test ("is any component of this reward server-owned?") and takes the same
   branch when the answer is yes: send the intent, WAIT for the verdict, and
   write NOTHING locally except the once-guard mark. `renown.js claimRank`,
   `collection-log.js claimMilestone` and `legacy.js claimQuestReward` all say so
   in those words at their call sites.

   The tests for those sites used to run client-authoritative, where the local
   grant WAS the payout, and asserted `G.gold` went up. That is now the one thing
   that must NOT happen. This fixture drives the branch that ships:

     · `HearthriseGoalClaim` is the transport (a plain PostgREST RPC, not a gold
       verb), so it is stubbed — `isSignedIn` true, every `claim*` recorded and
       answered — and the CLIENT logic above it is left entirely real;
     · the reward lands the way it really does, on a later envelope, which a
       test asks for explicitly with `rig.credit({gold: N})` rather than getting
       for free — because "the balance moved" and "the claim was recorded" are
       two different properties and conflating them is what the old shape did.

   rig = { calls, reply(fn), credit(state) }. `answer` seeds the verdict for
   every verb; `reply` overrides per call. */
export const withClaimServer = (answer, fn) => {
  const GC = window.HearthriseGoalClaim;
  if (!GC) return fn({ calls: [], reply: () => {}, credit: () => {} });
  const VERBS = ['claimDaily', 'claimQuest', 'claimMilestone', 'claimRank', 'claimGoal', 'grantCompanion'];
  const saved = {};
  const calls = [];
  let replyFn = null;
  for (const v of VERBS) {
    if (typeof GC[v] !== 'function') continue;
    saved[v] = GC[v];
    GC[v] = function (...args) {
      calls.push({ verb: v, args });
      const r = replyFn ? replyFn(v, args, calls) : null;
      return Promise.resolve(r || answer || { ok: true });
    };
  }
  const savedSignedIn = GC.isSignedIn;
  GC.isSignedIn = () => true;
  const rig = {
    calls,
    reply: (f) => { replyFn = f; return rig; },
    /* THE REWARD, ARRIVING THE WAY IT ARRIVES: an absolute server state through
       the real applyRecord. Never a local `G.gold +=`. */
    credit: (state) => serverGrants(state || {}),
  };
  const restore = () => {
    for (const v of Object.keys(saved)) GC[v] = saved[v];
    GC.isSignedIn = savedSignedIn;
  };
  let r;
  try { r = fn(rig); } catch (e) { restore(); throw e; }
  if (r && typeof r.then === 'function') return r.then((v) => { restore(); return v; }, (e) => { restore(); throw e; });
  restore();
  return r;
};

/* -- serverGrants - "THE SERVER SAYS YOU NOW HAVE THIS", WITH NO ROUND TRIP --
   The sibling of `withServerBacked` for the tests whose subject is NOT the
   gesture. A collection milestone's REWARD is claimed through a verb (that is
   `withServerBacked`'s job); a Renown PERK, a property rung or a marks balance
   is simply a number the server states and the client renders - and a test of
   the RENDER should not have to fake a purchase to get one.

   It is the same faithful path `stampRecordLikeLoad` documents: values are set
   on G, then pushed through the REAL `applyRecord` as a properly shaped hr_load
   envelope, so `recordValue`/`balanceOf`/`roomsOf`/`marksOf` all report `server`
   afterwards. Nothing pokes `_record`.

   FIELDS THAT ARE NOT FLAT SCALARS GO ON G FIRST. `rooms` ships as `progress[]`
     rows and `skills`/`equipment` as top-level siblings, which is why they are
     read off G rather than passed here: `G.rooms = {kitchen: 1}; serverGrants()`
     is the whole idiom, and it is the same three placements hr_state_of uses. */
const serverGrants = (state) => stampRecordLikeLoad(window.G, { state: state || {} });

/* -- withCompanionRoster - THE ROSTER ARRIVES THE WAY THE SERVER SENDS IT ----
   Under the capstone the starter fox is NOT seeded by the client: companions.js
   `ensureState` fails CLOSED to an empty roster and `accrue.js
   reconcileCompanions` rebuilds it from `res.companions` on every envelope
   (seeding fox locally before that envelope lands would silently reset a player
   who owns more). Six tests in this file were passing only because an EARLIER
   test had left a fox in the ambient `G.companions` - order-dependent, and
   invisible until the tests that seeded it were retired.

   So the roster is installed the one honest way: through the real
   `reconcileCompanions`, from an envelope shaped like the server's. Restored
   afterwards, because `G.companions` is ambient state the next test inherits. */
/* -- awaySpan - THE AWAY ENGINE, DRIVEN WHERE IT ACTUALLY LIVES (b515) ------
   THE PROBLEM. Thirty-one tests in this file measured "an absence pays" by
   calling `window.processOffline()` and reading `G`. b515 deleted the ~500-line
   local away engine that used to sit behind that call: the client no longer
   simulates an absence at all — it asks hr-accrue and applies the envelope. A
   test that still drives that caller measures nothing, and (worse) several of
   them ALSO read `G.skills` / `G.gold`, which are SERVER-OF-RECORD and ARMED,
   so even a working local grant could not land in them.

   WHERE THE PROPERTY WENT. `src/core/combat-sim.js`, `skill-sim.js` and
   `artisan-sim.js` ARE the away engine — tools/pack-edge.mjs vendors them
   verbatim into the Edge Function, so a span simulated here is the same bytes
   the server runs (AWAY-1 / AWAY-12 are that contract). They are pure: `state`
   is a plain object, every impure edge is injected, and "missing handlers are
   no-ops" (combat-sim.js's own header). So the honest rig is the one AWAY-15
   and AWAY-12c already use — a bare `simulateSpan` on a plain object — with an
   `fx` that RECORDS instead of one that writes the live G.

   WHY THAT IS STRONGER THAN WHAT IT REPLACES, not weaker:
     · it cannot pass because the client authored a number (nothing reaches G);
     · it cannot pass because an earlier test left state behind (`state` is
       built fresh, and `window.G` is never touched);
     · it is deterministic (a pinned seed, fixed rolls), so a payout assertion
       is an equality rather than a "> 0" that a lucky ambient stack satisfies;
     · it runs in the shape Deno runs, so it fails when a browser-only
       dependency creeps into the engine.

   WHAT IT DELIBERATELY DOES NOT COVER: the CALLER. "processOffline asks the
   server and applies what comes back" is b337-ON + B340-8 + the applyEnvelope
   battery; this rig is about the simulation, and a test that needs both says so.

   rig = { out, state, paid } - `out` is simulateSpan's payload, `state` is the
   mutated plain state, `paid` is what fx was ASKED to grant (xp per skill, gold,
   items, kills). Options: { monster, spanMs, fromMs, seed, tickMs, state, ctx, fx }.
   `playerRolls`/`monsterRolls` default to an always-hit, never-hurt pair so a
   span's payout is a function of the span and not of a death; a test about
   dying supplies its own. */
export const awaySpan = (o) => {
  const opts = o || {};
  const C = window.HearthriseCore;
  const monsterId = opts.monster || 'slime';
  const m = window.MONSTERS[monsterId];
  const fromMs = Number.isFinite(opts.fromMs) ? opts.fromMs : Date.UTC(2026, 0, 15, 6, 0, 0);
  const spanMs = Number.isFinite(opts.spanMs) ? opts.spanMs : 3600000;
  const state = Object.assign({
    activeMonster: monsterId,
    monsterHp: m ? m.hp : 10, monsterMaxHp: m ? m.hp : 10,
    playerHp: 9999, playerMaxHp: 9999,
    stats: { kills: 0, crits: 0, deaths: 0, rareDrops: 0 },
    skills: {}, inventory: {}, buffs: [], recoveringUntilMs: 0,
  }, opts.state);
  const paid = { xp: {}, gold: 0, items: {}, kills: 0, deaths: 0, ate: 0 };
  const fx = Object.assign({
    addXp: (skill, amount) => { paid.xp[skill] = (paid.xp[skill] || 0) + amount; },
    onLoot: (gp) => { paid.gold += gp; },
    addItem: (id, qty) => { paid.items[id] = (paid.items[id] || 0) + (Number(qty) || 1); },
    onKill: () => { paid.kills++; },
    onDeath: () => { paid.deaths++; },
  }, opts.fx);
  const out = C.combatSim.simulateSpan(state, Object.assign({
    away: opts.away !== false,
    fromMs, toMs: fromMs + spanMs,
    tickMs: Number.isFinite(opts.tickMs) ? opts.tickMs : 2400,
    rng: C.rngMod.createRng(Number.isFinite(opts.seed) ? opts.seed : 0xC0FFEE),
    monsters: window.MONSTERS,
    playerRolls: () => ({ accuracy: 1e9, maxHit: 40, critChance: 0 }),
    monsterRolls: () => ({ accuracy: 0, maxHit: 0 }),
    weakness: () => ({ dropMult: 1 }),
    bonus: () => 0,
    fx,
  }, opts.ctx));
  return { out, state, paid };
};

/* The GATHER twin of `awaySpan`, same contract and the same reasons. The node
   INDEX is the one thing the caller must supply (the server holds one id and no
   skill column, so the index is what says which skill an id belongs to), and it
   is built from the shipped catalogues rather than a fixture so a renamed node
   fails here instead of passing against a private copy. */
export const awayGatherSpan = (o) => {
  const opts = o || {};
  const C = window.HearthriseCore;
  const nodes = C.skillSim.indexGatherNodes({
    woodcutting: window.TREES, mining: window.ROCKS, fishing: window.FISH_SPOTS,
  });
  const targetId = opts.targetId
    || ((window.TREES || []).filter((t) => (t.req || 1) <= 1)[0] || {}).id;
  const skill = (nodes[targetId] || {}).skill || 'woodcutting';
  const fromMs = Number.isFinite(opts.fromMs) ? opts.fromMs : Date.UTC(2026, 0, 15, 6, 0, 0);
  const spanMs = Number.isFinite(opts.spanMs) ? opts.spanMs : 3600000;
  const state = Object.assign({
    activeSkill: skill, skillTargetId: targetId,
    skills: {}, inventory: {}, buffs: [], toolCarry: {}, stats: {}, equipment: {},
  }, opts.state);
  const paid = { xp: {}, items: {} };
  const fx = Object.assign({
    addXp: (sk, amt) => { paid.xp[sk] = (paid.xp[sk] || 0) + amt; },
    addItem: (id, qty) => { paid.items[id] = (paid.items[id] || 0) + (Number(qty) || 1); },
  }, opts.fx);
  const out = C.skillSim.simulateSkillSpan(state, Object.assign({
    away: opts.away !== false,
    fromMs, toMs: fromMs + spanMs,
    nodes, items: window.ITEMS,
    rng: C.rngMod.createRng(Number.isFinite(opts.seed) ? opts.seed : 0xC0FFEE),
    bonus: () => 0,
    fx,
  }, opts.ctx));
  return { out, state, paid, nodes, targetId, skill };
};

/* The ARTISAN twin of `awaySpan`. Unlike the other two its `fx` MUTATES the
   plain state's bag, because the bench's stop condition is "the inputs ran
   out" — a recorder that only counted would let the span cook for ever and the
   "no free food, no lost food" assertion would be measuring nothing. */
export const awayArtisanSpan = (o) => {
  const opts = o || {};
  const C = window.HearthriseCore;
  const recipes = C.artisanSim.indexArtisanRecipes(window.ARTISAN_RECIPES);
  const targetId = opts.targetId || 'cook_shrimp';
  const skill = (recipes[targetId] || {}).skill || 'cooking';
  const fromMs = Number.isFinite(opts.fromMs) ? opts.fromMs : Date.UTC(2026, 0, 15, 6, 0, 0);
  const spanMs = Number.isFinite(opts.spanMs) ? opts.spanMs : 7200000;
  const state = Object.assign({
    activeSkill: skill, skillTargetId: targetId,
    skills: {}, inventory: {}, buffs: [], toolCarry: {}, stats: {}, rooms: {}, equipment: {},
  }, opts.state);
  const paid = { xp: {}, items: {}, removed: {} };
  const fx = Object.assign({
    addXp: (sk, amt) => { paid.xp[sk] = (paid.xp[sk] || 0) + amt; },
    addItem: (id, qty) => {
      const q = Number(qty) || 1;
      paid.items[id] = (paid.items[id] || 0) + q;
      state.inventory[id] = (state.inventory[id] || 0) + q;
    },
    removeItem: (id, qty) => {
      const q = Number(qty) || 1;
      paid.removed[id] = (paid.removed[id] || 0) + q;
      state.inventory[id] = Math.max(0, (state.inventory[id] || 0) - q);
    },
  }, opts.fx);
  const out = C.artisanSim.simulateArtisanSpan(state, Object.assign({
    away: opts.away !== false,
    fromMs, toMs: fromMs + spanMs,
    recipes, items: window.ITEMS,
    rng: C.rngMod.createRng(Number.isFinite(opts.seed) ? opts.seed : 0xC0FFEE),
    bonus: () => 0,
    fx,
  }, opts.ctx));
  return { out, state, paid, recipes, targetId, skill };
};

/* -- applyAwayEnvelope - THE WELCOME-BACK RECEIPT, MADE THE WAY IT IS MADE ---
   `processOffline()` used to BUILD `G.lastOfflineSummary` itself; b515 deleted
   that. The receipt now arrives one way only: an accrual envelope carrying an
   `away` block goes through `applyServerEnvelope` (legacy.js), which applies the
   state, translates the payload with `accrue.js summaryFromAway`, credits the
   away kills, saves, repaints, and raises the ONE toast. Every one of those
   links is real here; only the network is absent.

   The toasts are captured rather than suppressed, because for three of the tests
   that use this the toast IS the subject ("the last thing the player reads").

   ⚠ KNOWN GAP, NAMED WHERE A READER WILL MEET IT (filed 2026-09-07, P1, routed
     to Backend + Systems). The SERVER's `away:` payload — hr-accrue/index.ts
     ~1163 — does not carry `stoppedBy`, `stoppedById`, `deaths`, `recoverMs`,
     `recoverRemainingMs`, `recoverLadder`, `burnt`, `buffPaidMs` or
     `buffsExpired`, and `summaryFromAway` additionally hardcodes `burnt: 0`.
     The ENGINE produces all of them (`accrual.js` journals `meta.stopped` /
     `meta.out_of`); they are dropped at the response boundary. So a test that
     puts them on the `away` block here is grading the TRANSLATOR and the
     RENDERER, which is real coverage of real client code — and is NOT a claim
     that the field reaches a live player. It does not. See
     .claude/coordination/DISCOVERIES.md. */
export const applyAwayEnvelope = (away, opts) => {
  const o = opts || {};
  const G = window.G;
  const A = window.HearthriseAccrual;
  /* DO NOT CLEAR THE AWAY HOLDER HERE. It is tempting (an away fixture
     landed by an earlier test is otherwise still on the Home screen for thirty
     minutes of suite time) and it is WRONG: accrue.js holds the last
     away-classified receipt precisely so that the 90-second syncs a test lands
     AFTER a night cannot evict the night's card, and a reset on this path would
     make that property untestable by erasing it one line before it is graded.
     The hygiene half belongs in the TEARDOWN of every test that states an away
     receipt (`__resetAwayReceipt()` in its finally). */
  const skills = {};
  for (const k of Object.keys(G.skills || {})) skills[k] = { xp: G.skills[k] };
  const env = Object.assign({
    ok: true, accrued: true,
    version: Math.max(((G._record && Number(G._record.version)) || 0) + 1, Date.now()),
    now: new Date().toISOString(),
    state: Object.assign({ slot: 0, gold: G.gold, active_kind: 'idle', active_id: null }, o.state),
    skills, inventory: Object.assign({}, G.inventory),
    away: away || {},
  }, o.env);
  const realNotify = window.notify;
  const toasts = [];
  const wasAck = A.isReplacementAcknowledged();
  try {
    A.acknowledgeReplacement(true);
    window.notify = function (m) { toasts.push(String(m)); };
    window.applyServerEnvelope(env, { intent: false });
  } finally {
    window.notify = realNotify;
    A.acknowledgeReplacement(wasAck);
  }
  return { toasts, last: toasts[toasts.length - 1] || '', rec: G.lastOfflineSummary, env };
};

export const withCompanionRoster = (owned, equipped, fn) => {
  const G = window.G;
  const A = window.HearthriseAccrual;
  const prev = G.companions ? JSON.parse(JSON.stringify(G.companions)) : undefined;
  const xp = {};
  const ids = [];
  for (const e of (owned || [])) {
    if (typeof e === 'string') ids.push(e);
    else if (e && e.id) { ids.push(e.id); if (e.xp) xp[e.id] = e.xp; }
  }
  if (A && typeof A.reconcileCompanions === 'function') {
    A.reconcileCompanions(G, { companions: { owned: ids, xp, equipped: equipped || null } });
  }
  try { return fn(); } finally {
    if (prev === undefined) { try { delete G.companions; } catch (e) {} } else G.companions = prev;
  }
};

/* ── b369 — HOW THE SUITE ARMS THE ENVELOPE FLIP, AND THE ONLY WAY IT MAY ────
   From b369 the absolute envelope arms on ONE fact: the server acknowledged an
   equip round trip in this session (src/net/equip.js, the arming block). There
   is deliberately no `__armForTest()` seam — a seam that arms without a round
   trip is the live b367 hole wearing a test-shaped name, and b367 is exactly
   what "the client asserts it is wired" was worth.

   So arming costs a REAL `sendEquip` through a stubbed `fetch`: the same bytes
   the browser runs, answered the way the server answers. The envelope applier
   is detached for the call — this round trip exists to prove DELIVERY, and
   letting it write the live G would make every test that arms the flip also a
   test of the applier. */
export async function armEquipFlipForTest(E, cfg) {
  const realFetch = window.fetch;
  const prevHooks = E.getEquipHooks();
  window.fetch = () => Promise.resolve(new Response(JSON.stringify({
    ok: true, verb: 'equip', version: 1, now: new Date().toISOString(),
    state: {}, skills: {}, inventory: {}, equipment: {},
  }), { status: 200, headers: { 'Content-Type': 'application/json' } }));
  try {
    E.configureEquip(cfg
      || { url: 'https://example.test', apiKey: 'k', token: 't', slot: 0, gestureWired: true });
    E.setEquipHooks({ onEnvelope: null });
    return await E.sendEquip({ weapon: 'iron_sword' }, {});
  } finally {
    E.setEquipHooks(prevHooks);
    window.fetch = realFetch;
  }
}

/* ══════════════════════════════════════════════════════════════════════════
   b353 — THE RUNNERS FOR THE **LOCAL AWAY PATH**, WHICH IS NOW THE OFF POSITION.
   ══════════════════════════════════════════════════════════════════════════
   The server-authority switch defaults ON from b353 (see B353-1). `processOffline()`
   therefore returns at the authority gate before it credits anything, which is
   the entire point — and it means every test that drives the LOCAL away
   simulation through `processOffline` measured nothing the moment the flip
   landed. Twenty-nine of them went red in one run.

   The wrong fix is to delete them or to pin the switch off for the whole suite.
   These tests are not obsolete and the code they cover is not dead:

     · `src/core/*` IS the server. combat-sim / skill-sim / artisan-sim are
       vendored into the Edge Function by tools/pack-edge.mjs, so AWAY-1's
       parity fixture and the b303/b305 batteries are asserting the bytes the
       SERVER runs. Losing them would be losing the only executable check on the
       accrual engine's simulation.
     · the local path still ships, behind the kill switch, and a kill switch
       whose off position is untested is not a kill switch.

   So they run in the position they are about: OFF, pinned per test, restored to
   PRISTINE (which is ON) afterwards — never left off for whatever runs next.
   The runner is named for the reason rather than the mechanism, so the next
   reader learns which half of the program a test belongs to from its
   registration line.

   ⚠ A TEST REGISTERED HERE IS A TEST THAT DOES **NOT** COVER THE SHIPPING
     DEFAULT. Anything asserting server-authoritative behaviour must stay on
     plain tryRun. */
/* ══════════════════════════════════════════════════════════════════════════
   b515 — WHAT THIS RUNNER HAS BECOME, AND WHY IT IS RENAMED RATHER THAN KEPT.
   ══════════════════════════════════════════════════════════════════════════
   It was `tryRunClientAuthoritative`: it turned the b353 kill switch OFF for the
   duration, and its header warned in capitals that "A TEST REGISTERED HERE IS A
   TEST THAT DOES NOT COVER THE SHIPPING DEFAULT". Forty-nine tests were
   registered on it.

   The switch is retired. `setServerAccrualEnabled` is a logging no-op, so the
   pin selected NOTHING — and a runner whose name and header both describe a
   position it cannot reach is worse than no runner at all: every test on it
   silently claimed to be covering the off position while actually running the
   on one. Forty-four of those tests are re-pointed or retired in this change.
   The five that remain never depended on the pin; what they DO depend on is the
   other half of what `unpinClientAuthoritative` did, which had nothing to do
   with the switch and was never in its name:

     THE POST-TEST RE-STAMP. A test that moves `G.gold`/`G.gems` leaves the boot
     stamp STALE for the ambient live G, so the next test's balance read
     fail-closes to UNKNOWN and every affordability-gated action refuses. That is
     a harness artifact and it is contagious — it was measured taking ~48
     economy/UI tests down at once. `stampBalanceLikeLoad` re-establishes the
     stamp the way `hr_load` does.

   So the runner keeps that job under a name that says it, and loses the claim it
   can no longer make. Scoped to the MUTATOR category, deliberately, exactly as
   the old header said: a blanket per-test stamp would hide a real regression in
   which production forgot to re-stamp after a server write (the b347/b356
   `client-overwrote` fault). */
export const tryRunRestampingBalance = (name, fn) => {
  try { return tryRun(name, fn); }
  finally { try { stampBalanceLikeLoad(window.G); } catch (e) {} }
};
const tryRunAsyncRestampingBalance = (name, fn) => tryRunAsync(name, fn).then(
  (r) => { try { stampBalanceLikeLoad(window.G); } catch (e) {} return r; },
  (e) => { try { stampBalanceLikeLoad(window.G); } catch (_e) {} throw e; });

// b219: the game tick runs THROUGH the suite, and earlier tests leave combat
// or gathering active — so a genuine "Defeated Slime" toast can land in
// #notifs in the middle of a toast test. Locate a test's own toast by a
// unique marker instead of grabbing whatever is first in the DOM.
export const findToasts = (mark) =>
  [...document.querySelectorAll('#notifs .notif:not(.leaving)')]
    .filter((n) => n.textContent.indexOf(mark) >= 0);
export const findToast = (mark) => findToasts(mark)[0] || null;

// b127: snapshot every field the player-action tests can mutate.
// Missing fields here = the test pollutes the player's save.
/* b371 — MEASURE THE FIGHT SCREEN WITHOUT DEPENDING ON WHICH TAB IS OPEN.
 *
 * Layout tests in this suite have a systemic weakness: the suite runs ~800
 * assertions in sequence and many of them switch tabs, so a test that measures
 * "the Fight screen" measures whatever the tests before it happened to leave
 * behind. Two b371 tests were written that way and both PASSED with their
 * defect planted — the elements measured 0x0, the tests took their skip branch,
 * and a skip renders identically to a pass. The mutation harness found it; no
 * amount of reading would have.
 *
 * This forces `#panel-combat` active and its view attribute to `fight` for the
 * duration of one synchronous measurement, then restores EXACTLY what it found
 * — including the case where the attribute was absent, which is different from
 * the case where it was `table`. It deliberately does not call `showTab`: that
 * fires renderers, tick wrappers and save writes, and a measurement should not
 * be able to change the player's state.
 */
export function withFightScreen(fn) {
  const panel = document.getElementById('panel-combat');
  if (!panel) return null;
  const hadActive = panel.classList.contains('active');
  const hadView = panel.hasAttribute('data-combat-view')
    ? panel.getAttribute('data-combat-view') : null;
  const prevInline = panel.getAttribute('style');
  try {
    panel.classList.add('active');
    panel.setAttribute('data-combat-view', 'fight');
    // Force layout so the measurements below see the new state.
    void panel.offsetHeight;
    return fn();
  } catch (e) {
    return null;
  } finally {
    if (!hadActive) panel.classList.remove('active');
    if (hadView === null) panel.removeAttribute('data-combat-view');
    else panel.setAttribute('data-combat-view', hadView);
    if (prevInline === null) panel.removeAttribute('style');
    else panel.setAttribute('style', prevInline);
  }
}

/* ══════════════════════════════════════════════════════════════════════════
   b455 — MEASURING A GRANT THE WAY THE ENGINE ACTUALLY PAYS IT

   Under the record arm the client no longer writes `G.skills`: the field belongs
   to the server, and a grant is a DISPLAY PREDICTION (src/net/predict.js) added
   on top of it. So the classic measurement —

       G.skills.woodcutting = 0; addXp('woodcutting', n); return G.skills.woodcutting;

   — reads 0 armed, and every pacing/bonus/away test built on it silently stops
   proving anything. These two helpers are the same reads the GAME uses
   (`window.skillXp` is the display accessor, byte-identical to the raw read while
   dormant), so a test written with them is correct in both states and does not
   have to know which one it is in.

   ⚠ `xpZero` CLEARS THE PREDICTION as well as the field. Zeroing only G.skills
     would leave an earlier test's outstanding prediction on the display and the
     next measurement would read a grant it did not make.
   ══════════════════════════════════════════════════════════════════════════ */
export const xpOf = (sk) => (typeof window.skillXp === 'function'
  ? window.skillXp(sk)
  : ((window.G && window.G.skills && window.G.skills[sk]) || 0));
/** The whole DISPLAY skills map, for the before/after diffs that measure a total
 *  gain across every skill at once (an away kill pays four of them). */
export const xpMap = () => (typeof window.hrDisplaySkills === 'function'
  ? window.hrDisplaySkills()
  : Object.assign({}, (window.G && window.G.skills) || {}));
export const predZero = () => {
  try {
    const P = window.HearthrisePredict;
    if (P && typeof P.resetPredictions === 'function') P.resetPredictions(window.G);
  } catch (e) {}
};
export const xpZero = (sk) => {
  const G = window.G;
  if (G && G.skills) G.skills[sk] = 0;
  predZero();
  return xpOf(sk);
};
/** The GOLD twin, for the same reason: a kill's loot is a prediction under the
 *  arm, so `G.gold` alone no longer measures what the engine paid. */
export const goldOf = () => {
  const B = window.HearthriseBalance;
  if (B && typeof B.balanceNumForDisplay === 'function') {
    const n = B.balanceNumForDisplay(window.G, 'gold');
    if (typeof n === 'number') return n;
  }
  return (window.G && Number(window.G.gold)) || 0;
};
/** The GEM twin, for the same reason — `gems` is server-of-record and armed, so
 *  a bare `G.gems` is not what any affordability read or any surface uses. */
export const gemsOf = () => {
  const B = window.HearthriseBalance;
  if (B && typeof B.balanceNumForDisplay === 'function') {
    const n = B.balanceNumForDisplay(window.G, 'gems');
    if (typeof n === 'number') return n;
  }
  return (window.G && Number(window.G.gems)) || 0;
};

/* ══ THE ABSENT SEAL — snapshotG NEEDS NO "DECLARED EMPTY" ═══════════════
   `JSON.stringify` DROPS an undefined value, so a BARE entry below (`rooms: G.rooms`) put
   NOTHING back for a character who does not own it and the write leaked into every later test
   (MEASURED 2026-09-12 via `buyback` and `rooms`). The fix is not 26 guessed empties — one is
   state a later test reads as real (`skills: {}` is a level-1 character) — so absence is
   RECORDED as the `SNAP_ABSENT` sentinel and `restoreG` `delete`s that key. WHICH 26 and why:
   snapshot-allowlist-guard §1b. UNRESOLVED: none; the 13 pre-seal empties stand, pinned. */
const SNAP_ABSENT = ' HR_SNAP_ABSENT ';
/* ⚠ NOT one JSON round trip over the whole object — that IS the bug. The literal is built
   first (it keeps an `undefined`-valued key, which is how the absent fields stay
   enumerable), then each value is cloned or sentinelled. */
const sealSnapshot = (raw) => {
  const snap = {};
  for (const k of Object.keys(raw)) snap[k] = (typeof raw[k] === 'undefined') ? SNAP_ABSENT
    : (raw[k] && typeof raw[k] === 'object') ? JSON.parse(JSON.stringify(raw[k])) : raw[k];
  return snap;
};

export const snapshotG = () => {
  const G = window.G;
  if (!G) return null;
  const raw = {
    activeSkill: G.activeSkill,
    skillTargetId: G.skillTargetId,
    activeMonster: G.activeMonster,
    /* ⚠ ALL FOUR STRIP POINTERS, AND `|| null` IS LOAD-BEARING: `JSON.stringify` DROPS an undefined property, so a plain entry for a field nothing on G initialises restores nothing, and one test's run then stands for the whole suite. */
    activeArtisanRecipe: G.activeArtisanRecipe || null, activeArtisanSkill: G.activeArtisanSkill || null, activeAction: G.activeAction || null,
    gold: G.gold,
    gems: G.gems,
    inventory: G.inventory,
    equipment: G.equipment,
    companions: G.companions,
    farmPlots: G.farmPlots,
    rooms: G.rooms,
    quests: G.quests,
    clanName: G.clanName,
    skills: G.skills,
    stats: G.stats,
    plotBuildings: G.plotBuildings,
    playerHp: G.playerHp,
    playerMaxHp: G.playerMaxHp,
    // b136: include the new fields so Batch C tests don't pollute
    // the player's save when they mutate G.plotLevels / autoActions / dropLog.
    plotLevels: G.plotLevels,
    /* 2026-09-06 — the SERVER-mirrored plot tier (farm-progression.js
       getServerPlotLevel). It outranks plotLevels in the plant gate, so a test
       that leaves it set would unlock tier-2 crops for every later test — the
       hardest kind of order-dependent flake. Undefined restores as undefined,
       which is exactly "the server has not told us yet". */
    _serverPlotLevel: G._serverPlotLevel,
    autoActions: G.autoActions,
    dropLog: G.dropLog,
    // b138: launchpad — Batch D's tests touch lastActivity + daily.snapshot.
    lastActivity: G.lastActivity,
    daily: G.daily,
    // b213 QA: the house-room test raises the property tier to clear the
    // b201 room gate — snapshot it so the player's real tier is restored.
    homestead: G.homestead,
    /* The SERVER's dungeon re-entry windows (was `dungeons`, the client clock).
       `?? null` is load-bearing: JSON drops undefined and an account with no open
       window has no key at all, so a seeded one would outlive its own test. */
    _dungeonCooldowns: G._dungeonCooldowns ?? null,
    playerName: G.playerName,
    // b222 (SEAM 3): the Rested XP bank + its watermark. The seam tests fill
    // the bank directly and drive processOffline, so without these two fields
    // a test run would hand the player charges they never earned — or, worse,
    // leave a future-dated watermark that silently stops rest accruing.
    restedXp: G.restedXp,
    restedAt: G.restedAt,
    /* b456: `marks` moved from the nested G.bountyHunter.marks to a TOP-LEVEL
       record field and was never added here, so every test that touched it wrote
       straight through to the player's save. Snapshotting the nested mirror is not
       the same field any more. */
    marks: G.marks,
    // b226 (pacing retune): the offline DAILY budget and its watermark, the
    // renown high-water ratchet, and the Founder's-mark date. Every offline
    // test below drives the watermark directly — without these three fields a
    // suite run would hand the player free offline hours, or leave a
    // future-dated watermark that silently stops offline progress accruing.
    offlineBudget: G.offlineBudget,
    /* 2026-09-14 — `enchant` was missing from this allowlist while ELEM-5 and
       ELEM-5b both assign it, so a suite run in the LIVE page left the player
       wearing whichever element the last arm forged until the next envelope.
       NO `?? {}`: an un-enchanted character has NO enchant, and a pinned empty
       object is a VALUE a later test would read as real state — sealSnapshot
       records the absence and restoreG deletes the key back (SNAP-2b). */
    enchant: G.enchant,
    renownHigh: G.renownHigh,
    /* b494 — AND THE CLAIM LIST WITH IT. `renownHigh` was snapshotted and
       `renown` ({claimed, seenRank}) was not, yet four tests assign
       `G.renown = {claimed:[], seenRank:0}` to force a claimable ladder. It is
       RESIDUE (src/net/client-state.js), so a suite run in the live page ERASED
       the player's record of which rank rewards they had already taken and
       persisted the erasure — the ladder then re-offers ranks the server has
       already paid, and every one of those buttons can only answer
       `already_claimed`. The server once-guard means no gold moved either way;
       the damage was to what the player is shown. `collectionLog` ({claimed:[]})
       is the same field on the sibling surface, assigned by three tests, and was
       likewise unsnapshotted. */
    renown: G.renown,
    collectionLog: G.collectionLog,
    createdAt: G.createdAt,
    // b228: the Chronicle. The suite drives record()/reconcile() directly and
    // opens the panel (which stamps seenAt), so without this a run would write
    // test milestones into the player's permanent history and clear the badge
    // on real milestones they had not read yet.
    chronicle: G.chronicle,
    // b264: the bounty tests mutate active/board/autoBounty; snapshot it so one
    // test's leftover (e.g. autoBounty=1) can't leak into the next and, via
    // ensureBountyState regenerating an emptied board, trigger a spurious
    // auto-accept that flips a later test's outcome.
    bountyHunter: G.bountyHunter,
    /* The away-unification wave: `buffs` (the freeze tests hold one through a
       12h grant), and `toolCarry` — renamed from the `_`-prefixed scratch key
       so it reaches the cloud, which also means the suite can now pollute it. */
    buffs: G.buffs,
    toolCarry: G.toolCarry,
    /* b341: the survival forecast reads the auto-eat TRAIT and the FOOD SLOT,
       and every away test drives `lastSeen`. All three were mutable by the
       suite and unsnapshotted — AWAY-HONEST-3 clearing `auto_eat` would have
       taken a real player's 100-mark purchase with it, which is exactly the
       pollution this list exists to prevent. */
    /* `?? null`, not bare — SNAP-2: legacy.js's fresh-G literal has no `traits`
       key, JSON.stringify DROPS it, restoreG puts nothing back (27 leaks). */
    traits: G.traits ?? null,
    foodSlot: G.foodSlot,
    autoEatPct: G.autoEatPct,
    lastSeen: G.lastSeen,
    lastWelcome: G.lastWelcome || 0,   // a forgotten restore re-opens a dismissed card

    /* b345: the BESTIARY, and the reason is worth stating because it caught a
       real cross-test failure the moment a test finally killed a boss.
       `killMonster` stamps `G.bestiary[id] = {kills, firstKill}` (legacy.js),
       and `firstKill` is the ONE derived fact the Chronicle's seed is allowed
       to DATE — so a test that kills a boss and does not put the bestiary back
       leaves a dated first-kill in the save, and the very next run of
       "b228: reconcile SEEDS an existing save undated" fails on
       `every seeded entry must be undated`. MEASURED exactly that way while
       adding the b345 away-parity night, which fights the lich.
       It is also the player's collection log — a suite run must never write a
       first-kill date into a monster they have not met. */
    bestiary: G.bestiary,
    /* b348: the BANK. `goldBuys`/`gemBuys` are purchased permanent progress —
       one paid with escalating gold, one with real-money gems — and the suite
       buys space to prove the bag renders it. Every bank test to date restored
       it by hand in its own `finally`; that works right up until one does not,
       and the failure mode is silently gifting a player capacity they never
       bought (or, on the other branch, taking capacity they did). */
    bank: G.bank,
    /* The ENFORCED cap beside the rungs that price it — all `bankCap()` reads, so a
       test pinning it pins the bag for the rest of the run. `?? null`: no envelope
       yet = no key, and JSON drops undefined (SNAP-2). */
    _bankCap: G._bankCap ?? null,
    /* b4xx (gold slices 2-3): the WORKERS crew and the HOUSE theme/buyback state.
       The slice-2/3 tests drive hire() (which pushes a worker + debits gold),
       buyTheme() (equips a theme) and repurchase() (spends the buy-back list), so
       without these four fields a suite run would gift the player a worker, an
       equipped theme, or an emptied/edited buy-back list they never chose. */
    workers: G.workers,
    houseTheme: G.houseTheme,
    /* ⚠ `ownedThemes` / `ownedCosmetics` WERE HERE AND ARE GONE WITH THE FIELDS
       (2026-09-14): ownership of a gem unlock is the server's projected set now,
       and the two residue bags were deleted from `G` and from RESIDUE_FIELDS.
       What replaces them on this list is the SCRATCH the projection lands in.
       `_`-prefixed scratch is never persisted, but it absolutely outlives
       restoreG within a run — so a test that seeds an owned set and does not put
       it back hands the next test a wardrobe (or, worse, takes one away and makes
       an unrelated House assertion fail on a Buy button). Same reason `_bankCap`
       is here. BARE, no `?? null` — SNAP-2b fails the suite if that changes,
       because `null` would be a VALUE ("the realm answered and you own nothing")
       where the truth for a character whose envelope has not landed is ABSENCE.
       sealSnapshot records the absence and restoreG deletes the key. */
    _gemUnlocks: G._gemUnlocks,
    _recipeUnlocks: G._recipeUnlocks,
    /* ⚠ `?? []`, NOT bare — SNAP-2, and this one BIT: a character who never sold has
       no key, JSON drops it, restoreG cannot put back what it has not got, and a test
       that made a REAL sale left an entry render/shop.js paints as an extra row. */
    buyback: G.buyback ?? [],
    /* b487: the QUEST MODAL's two slates. `G.daily` (the DAILY_TASK_POOL tasks)
       has been on this list since b138 — its two SIBLINGS never were, and they
       are the ones the goal tests actually drive. GOAL-CLAIM-1 assigns
       `G.dailyGoals = {dayKey, picks:['kill_more'], startValues:{kill_more:0},
       claimed:{}}` and the b487 wk_bury heal test assigns `G.weeklyGoals` —
       both wrote straight through to the player's save, replacing today's real
       three dailies with one synthetic goal and forging a `claimed` flag on a
       weekly reward. A forged claimed flag is not cosmetic: the modal reads it
       as "already taken" and the player never presses Claim, so the reward is
       silently forfeited for the period. Same reason `bank` and `bestiary` are
       here — a suite run must never edit progression it did not earn. */
    dailyGoals: G.dailyGoals,
    weeklyGoals: G.weeklyGoals,
    /* RECOVERY (rev. 2) — the ABSOLUTE instant this character gets back up.
       `simulateSpan` WRITES it on the live G (src/core/combat-sim.js), and it
       is the most contagious field this list has ever been missing: a test that
       simulates a deadly night leaves a future-dated `recoveringUntilMs`
       behind, and every away fixture after it opens its window ALREADY DOWN —
       zero ticks, zero kills, `died:false`. MEASURED: the b341 simulation test
       leaking it took b342-1, COMBAT-UI-24 and the whole away family with it,
       each failing on "the fixture produced no kills" for a reason that had
       nothing to do with what they test. It is also real progression state on
       the live page, which is the other half of why it belongs here.
       ⚠ `|| 0`, NOT the bare read. This list goes through JSON, and JSON DROPS
         an `undefined` value — so a character who had never fallen snapshotted
         NOTHING for this field, `restoreG` then had no key to put back, and the
         poison survived the restore that exists to remove it. MEASURED exactly
         that way: COMBAT-UI-24 still opened an all-recovery night after b342-1
         had "restored" the state it inherited. A field that is only sometimes
         present is a field this list only sometimes protects. */
    recoveringUntilMs: G.recoveringUntilMs || 0,
    /* THE HERO-SLOT ENTITLEMENT AND ITS SERVER MIRROR — 13 SNAP-1 writes put
       back by hand in six `finally` blocks, and the seventh would have forgotten.
       A PAIR that must restore together (`_heroSlots` is `_` scratch, never
       persisted, but it outlives restoreG within a run — which is all it takes to
       hand the next test five heroes). ⚠ `?? null`: neither key is in the fresh-G
       literal, JSON drops undefined, a dropped key restores nothing (SNAP-2), and
       `null` reads as ABSENT at both consumers — the fail-safe direction. */
    heroSlotsUnlocked: G.heroSlotsUnlocked ?? null,
    _heroSlots: G._heroSlots ?? null,
    /* THE SELL-LOCK AND ITS LOOT-FILTER TWIN — both residue, both persisted by
       hr_put_client_state, and four tests were already writing `lockedItems` and
       putting it back by hand in their own `finally`. That is four authors
       remembering; this list is the suite remembering, and a suite run that
       silently UNLOCKS a player's protected stacks is the b494 class exactly.
       ⚠ `?? null` (not the bare read): neither key is in the fresh-G literal,
         JSON drops undefined, and a dropped key restores nothing (SNAP-2). Both
         read as ABSENT at every consumer — no lock, keep everything. */
    lockedItems: G.lockedItems ?? null,
    lootFilter: G.lootFilter ?? null,
  };
  return sealSnapshot(raw);
};

/* b226 — put the player "away" for N hours. The offline catch-up is
   watermarked on G.offlineBudget.at (the same defence Rested XP uses against
   the b214 double-pay class of bug), so moving `lastSeen` alone no longer
   simulates an absence — the watermark IS the clock, and a test that only
   moved lastSeen would be testing a field the engine no longer reads.
   Also refills the day's allowance, so a test never inherits another's spend. */
/* `nowMs` exists for tests that run the SAME absence twice and compare the two
   piles. Without it each call re-reads Date.now(), so the two runs are anchored
   milliseconds apart, and when that gap straddles a tick boundary the second
   night gets one more tick than the first — b227's offline-parity test failed
   about once in thirteen runs that way (11390 vs 11415 XP), which reads as a
   real parity break rather than as the harness moving underneath it. Pass one
   captured instant to both runs and the comparison is against a fixed clock.
   Defaulted, so every existing caller is unchanged. */
/* ══ REV. 2 — PUT THE CHARACTER BACK ON THEIR FEET ══════════════════
   Under the Recovery Rule a fall no longer ends an away night: the character is
   Knocked Out until an ABSOLUTE instant (`recoveringUntilMs`, written on G by
   src/core/combat-sim.js `simulateSpan`) and then resumes. That instant can sit
   up to the 64-minute cap in the FUTURE when a span ends — which is correct for
   a player, who lives one absence at a time, and poison for a FIXTURE, which
   routinely runs two overlapping absences from "identical state" and compares
   them. The second one then opens already face-down, simulates nothing, and the
   assertion below it reports "the caller paid nothing" for a caller that is
   working perfectly.
   MEASURED on four fixtures at once (b255, AWAY-HONEST-2, AWAY-BUDGET-1 and the
   b341 caller half), each failing on an empty night. Called wherever a fixture
   re-stands its fighter, beside the `playerHp = playerMaxHp` that has always
   been there and now covers only half of "on their feet". */
export const onFeet = () => { if (window.G) window.G.recoveringUntilMs = 0; };

export const setAway = (hours, nowMs) => {
  const G = window.G;
  const now = (typeof nowMs === 'number' && isFinite(nowMs)) ? nowMs : Date.now();
  const at = now - hours * 3600000;
  G.lastSeen = at;
  G.offlineBudget = {
    dayKey: (typeof window.utcDayKey === 'function') ? window.utcDayKey(now) : 0,
    usedMs: 0,
    at,
  };
  /* …AND THE CHARACTER IS ON THEIR FEET WHEN THE ABSENCE BEGINS (rev. 2) —
     see `onFeet` above. Stated here for the same reason the watermark is: this
     helper's whole job is "a fresh absence starts now". */
  onFeet();
};
/* THE INTENT TRANSPORT, ARMED AND PUT BACK — WRITTEN ONCE. The teardown is not boilerplate but a RULING ("pristine is ON, so clear the override first and re-apply OFF only if we started there") that had been copy-pasted thirteen times in four spellings. */
export const armActivityTransport = () => { const M = window.HearthriseActivity; M.resetActivity(); M.configureActivity({ url: 'https://proj.supabase.co', apiKey: 'anon', authToken: () => 'jwt' }); window.HearthriseAccrual.setServerAccrualEnabled(true); };
export const drain = async () => { for (let i = 0; i < 12; i++) await new Promise((r) => setTimeout(r, 0)); };   // LET AN INTENT'S PROMISE CHAIN FINISH. Was declared verbatim in four tests; one that needs a different wait still declares its own and shadows this.
export const restoreAccrualSwitch = (wasOn) => { const A = window.HearthriseAccrual; A.setServerAccrualEnabled(false); try { A.__clearAccrualOverride(); localStorage.removeItem('hr:serverAccrual'); } catch (e) {} if (!wasOn) A.setServerAccrualEnabled(false); };
/* ── THE NODE (AND THE RECIPE) YOU CAME FROM — ONE ARC, DRIVEN TWICE ─────────
   Reproduced three times on live: chop Willow → fight a Goblin → open Skills
   and tap Willow again → nothing at all. No intent, no toast, the header still
   reading "Fighting Goblin"; tapping OAK switched instantly. The dead tile was
   always the node the player CAME FROM, because every tile renderer baked
   `active ? stopSkill() : start(…)` at PAINT time while combat's cross-stop
   clears the pointer and strips the badge IN PLACE without rebuilding the panel
   (nor does walking back to Skills) — so that one tile kept a stop handler
   while looking idle and the stop returned in silence. Gather tiles and artisan
   tiles are the same bug and the same fix (render/activity-tile.js reads the
   live pointer at the click), so they are ONE scenario parameterised by node:
   this plays it as the player does — real .click()s on real tiles, real
   declaration path — asserts the two shared properties (it painted active; the
   fight really did cross-stop) and hands the test the tap it is about. It owns
   the try/finally, so a failed arm can never leak the fetch stub or an
   unrestored G into the rest of the suite. */
export const cameFromArc = async (cfg, body) => {
  const G = window.G; const M = window.HearthriseActivity; const realFetch = window.fetch; const wasOn = window.HearthriseAccrual.isServerAccrualEnabled(); const sent = [];
  window.fetch = function (u, init) {
    if (!/hr-accrue/.test(String(u))) return realFetch.apply(this, arguments);
    let b = null; try { b = JSON.parse(init && init.body); } catch (e) {} if (b && b.verb === 'set_activity') sent.push(b);
    const act = (b && b.activity) || { kind: 'idle', id: null };   /* ECHO THE DECLARED POINTER BACK as the server's own: a stub answering with a fixed activity reconciles the client onto something the gesture never asked for */
    return Promise.resolve(new Response(JSON.stringify({ ok: true, verb: 'set_activity', version: 700 + sent.length, now: null, activity: act, state: { active_kind: act.kind, active_id: act.id }, skills: {}, inventory: {} }), { status: 200 }));
  };
  const snap = snapshotG(); const tileOf = () => [...document.querySelectorAll('#skill-detail .act-tile')].find((e) => e.getAttribute('data-prod') === cfg.prod);
  const settle = async () => { for (let i = 0; i < 60; i++) await Promise.resolve(); await new Promise((r) => setTimeout(r, 0)); for (let i = 0; i < 60; i++) await Promise.resolve(); };
  try {
    armActivityTransport(); cfg.seed(G); G.playerHp = G.playerMaxHp || G.playerHp; window.openSkillDetail(cfg.skillId); await settle();
    cfg.start(); await settle(); const painted = tileOf();
    assert(!!painted && painted.classList.contains('active'), 'CONTROL: the ' + cfg.targetId + ' tile must paint ACTIVE while it runs (pointer ' + G.activeSkill + '/' + G.skillTargetId + '), or this cannot reproduce the stale paint');
    window.startCombat(cfg.mid); await settle();
    assert(G.activeMonster === cfg.mid && !G.activeSkill && !G.skillTargetId, 'setup: the fight or the cross-stop never happened (' + G.activeMonster + ', ' + G.activeSkill + ') — the scenario under test is gone');
    window.showTab('skills'); await settle();                       // the player walks back; measured: this does NOT repaint the grid
    const tile = tileOf(); const stalePaint = tile === painted; sent.length = 0; assert(!!tile && tile.isConnected, 'the ' + cfg.targetId + ' tile is no longer on the Skills screen');
    await body({ G, M, sent, settle, tileOf, tile, stalePaint });
  } finally {
    window.fetch = realFetch; restoreAccrualSwitch(wasOn); M.resetActivity(); M.configureActivity(null);
    try { window.stopSkill(); } catch (e) {} try { window.stopCombat(); } catch (e) {} restoreG(snap); window.showTab('profile');
  }
};
/* THE SIGNED-IN SERVER ENVIRONMENT, WRITTEN ONCE — five claim tests each carried
   the same four stubs and restores; a forgotten copy leaks a fake session. */
export const stubSignedIn = (slot) => {
  const o = [window.HearthriseSupabase, window.HearthriseAuth, window.HearthriseRpc, window.HearthriseProfile];
  window.HearthriseSupabase = { getConfig: () => ({ url: 'https://test.local', anonKey: 'k' }) };
  window.HearthriseAuth = { getSession: () => ({ user: { id: 'u' }, access_token: 't' }) };
  window.HearthriseRpc = { mayCall: () => true };
  window.HearthriseProfile = { activeSlot: () => slot };
  return () => {
    window.HearthriseSupabase = o[0]; window.HearthriseAuth = o[1];
    window.HearthriseRpc = o[2]; window.HearthriseProfile = o[3];
  };
};

/* ── THE RESIDUE PUT ON A STUBBED WIRE, WRITTEN ONCE ─────────────────────────
   `hr_put_client_state` is the ONE periodic write the armed game makes, and three
   tests drive it against a fake endpoint. Each carried the same fixture verbatim:
   release the reconcile hold (or the save returns before the network and every
   assertion is vacuous), swap `window.fetch`, trust the clock, reset the auth gate
   and the save health — then put all four back EXACTLY as found, plus the same
   nine-key cfg. Stated once so a failed arm cannot leak the stub or a probe's
   cloudSyncedAt into the suite. `onRequest(url, init)` answers any example.invalid
   call: a Response to control it, nothing for a 200 {ok:true}. */
export const withResidueWire = async (onRequest, body, extraCfg) => {
  const S = window.HearthriseSync, G = window.G;
  const realFetch = window.fetch, wasHeld = S.isSnapshotHeld();
  const savedSyncedAt = G ? G.cloudSyncedAt : undefined;
  const cfg = Object.assign({
    snapshotEndpoint: 'https://example.invalid/rest/v1/game_saves',
    claimEndpoint: null, apiKey: 'anon', userId: () => 'u1', authToken: () => 'opaque-token',
    onAuthError: async () => true, onAuthExpired: () => {},
    onSyncFailure: () => {}, onSyncRecovered: () => {},
  }, extraCfg || {});
  try {
    if (wasHeld) S.releaseSnapshots();
    window.fetch = function (u, init) {
      if (!/example\.invalid/.test(String(u))) return realFetch.apply(this, arguments);
      return onRequest(String(u), init) || Promise.resolve(new Response('{"ok":true}', { status: 200 }));
    };
    S.setClockTrusted(true); S.resetAuthGate(); S.__resetSyncHealth();
    return await S.__withConfig(cfg, () => body(S, cfg));
  } finally {
    window.fetch = realFetch;
    if (wasHeld) S.holdSnapshots();
    if (G) { if (savedSyncedAt === undefined) delete G.cloudSyncedAt; else G.cloudSyncedAt = savedSyncedAt; }
    S.resetAuthGate(); S.__resetSyncHealth();
  }
};

/* ── SEED THE PLAY STREAK THE WAY THE GAME NOW LEARNS IT (2026-09-14) ────────
   `G.streak` was a device-clock counter in the residue and is DELETED: the play
   streak is `player_state.streak_days`, mirrored into the `G._serverStreak`
   scratch by accrue.js reconcilePlayStreak and read through playStreakDays().
   A fixture that assigns `G.streak` now asserts against a field nothing reads,
   so it would pass or fail on the real account's data. This drives the SHIPPED
   reconcile with a projected envelope — the same path a settle takes.
   `null` clears the observation (back to never-observed, which reads 0). */
/* ── M5 — A FRESH PROBE CHARACTER GETS A FRESH FRAME FLOOR ─────────────────
   accrue.js's frame gate (WORLD_TICK_DESIGN.md §7.1) refuses any envelope whose
   `version` is not STRICTLY greater than the last one this client applied, and
   the floor is per CHARACTER. Production's boundary is a slot change and goes
   through resetGold(); `restoreG` covers the suite's equivalent. What neither
   covers is a test that builds SEVERAL private probe characters inside one
   block and applies the same fixture envelope to each — three different people
   in production, one floor here, and the second and third applies are dropped
   as duplicates for a reason that has nothing to do with what the test is
   about. Call this between them and say which character is next.

   ⚠ NOT A WAY TO RE-APPLY AN ENVELOPE TO THE **SAME** CHARACTER. If a fixture
     needs a second server statement for one character, the faithful fix is a
     HIGHER version — that is what a real server would send, and reaching for
     this instead would hide exactly the duplicate the gate exists to catch. */
export const freshFrameGate = () => {
  try {
    const A = window.HearthriseAccrual;
    if (A && typeof A.resetFrameGate === 'function') A.resetFrameGate();
  } catch (e) {}
};

export const seedPlayStreak = (n) => {
  const A = window.HearthriseAccrual;
  if (!A || typeof A.reconcilePlayStreak !== 'function' || !window.G) return;
  if (n === null || n === undefined) { delete window.G._serverStreak; return; }
  A.reconcilePlayStreak(window.G, { ok: true, state: { streak_days: n, streak_day_key: null } });
};

/* The nine purged names plus the scratch they were replaced by — saved and put
   back around every RESIDUE-PURGE block, because none of them is in snapshotG. */
const RESIDUE_PURGE_KEYS = ['streak', 'toolCarry', 'combatStyle', 'ownedThemes', 'ownedCosmetics',
  'heroSlotsUnlocked', 'autoEatPct', 'foodSlot', 'renownHigh', 'autoActions',
  '_serverStreak', '_gemUnlocks', '_heroSlots'];
export const residuePurgeSnap = (G) => {
  const out = {};
  RESIDUE_PURGE_KEYS.forEach((k) => {
    out[k] = Object.prototype.hasOwnProperty.call(G, k) ? G[k] : undefined;
  });
  return out;
};
export const residuePurgeRestore = (G, snap) => {
  try { window.HearthriseRenown.__resetClaimState(); } catch (e) {}
  RESIDUE_PURGE_KEYS.forEach((k) => { if (snap[k] === undefined) delete G[k]; else G[k] = snap[k]; });
};

export const restoreG = (snap) => {
  if (!snap || !window.G) return;
  /* ⚠ THE OTHER HALF OF `sealSnapshot`: `delete` is NOT interchangeable with `= null`. */
  for (const k of Object.keys(snap)) { if (snap[k] === SNAP_ABSENT) delete window.G[k]; else window.G[k] = snap[k]; }
  /* b455 — AND THE DISPLAY PREDICTIONS GO WITH IT. Restoring G.skills/G.gold
     while leaving an outstanding prediction standing would carry one test's
     grant into the next test's measurement, which is the hardest kind of suite
     flake to find (it only appears in a particular ORDER). */
  try {
    const P = window.HearthrisePredict;
    if (P && typeof P.resetPredictions === 'function') P.resetPredictions(window.G);
  } catch (e) {}
  /* M5 — AND THE FRAME FLOOR GOES WITH IT, for the same reason one rung down.
     accrue.js's frame gate (WORLD_TICK_DESIGN.md §7.1) refuses any envelope
     whose `version` is not STRICTLY greater than the last one applied, and the
     floor is per CHARACTER. `restoreG` is the moment this suite swaps one
     character for another, and a test that applied an envelope stamped
     `Date.now()` would otherwise leave a floor of ~1.7e12 in front of every
     later test that uses a small fixture version — refused, silently, and only
     in a particular ORDER. Production's equivalent boundary is a slot change,
     which goes through resetGold() and resets the same floor. */
  try {
    const A = window.HearthriseAccrual;
    if (A && typeof A.resetFrameGate === 'function') A.resetFrameGate();
  } catch (e) {}
  if (typeof window.stopSkill === 'function' && window.G.activeSkill) try { window.stopSkill(); } catch {}
  if (typeof window.stopCombat === 'function' && window.G.activeMonster) try { window.stopCombat(); } catch {}
};

/* b456 — RESTORE THE RECORD WITH THE STATE, for a test that drove a REAL load.
   `loadLocal()` ends with the belt-and-braces `forgetServerOfRecord(G)`, which
   DELETES every server-of-record field off the live G and clears the `known`
   list. That is correct for a load (the envelope supplies them next) and it is
   catastrophic for the suite: a test that runs a real load and then restores only
   the fields it named leaves G with no skills, no equipment, no rooms and no
   balance, and every test after it fails for a reason that has nothing to do with
   what it is testing. MEASURED: wrapping B340-3 in `withLocalBlob` (so loadLocal
   actually ran again) took ACT-1 and four COMBAT-UI tests down with it.
   This puts the values back AND re-stamps them through the real applyRecord path,
   so the ambient G the next test inherits is a loaded character rather than a
   stripped one. */
export const restoreGAndRecord = (snap) => {
  restoreG(snap);
  try { stampRecordLikeLoad(window.G); } catch (e) {}
};

/* SNAP-2's PROBE. Walked once per property test below, so a red names WHICH half of the
   seal broke. Per field: a character that does NOT own it (snapshot → write what a test
   writes → restore) and one that DOES. A swap onto a DETACHED copy, synchronous, so the
   live G is never written. DECLARED_EMPTY is the 13 pre-seal `?? <empty>` entries PINNED
   BY VALUE — a field may decline the sentinel only if named here with its exact value, so
   the count can only fall; a made-up empty is worse than the leak it replaces. */
const SNAP_DECLARED_EMPTY = {
  activeArtisanRecipe: null, activeArtisanSkill: null, activeAction: null, _dungeonCooldowns: null,
  traits: null, _bankCap: null, heroSlotsUnlocked: null, _heroSlots: null, lockedItems: null,
  lootFilter: null, lastWelcome: 0, recoveringUntilMs: 0, buyback: [],
};
export const snapRoundTrip = () => {
  const own = (o, k) => Object.prototype.hasOwnProperty.call(o, k), J = (v) => String(JSON.stringify(v)).slice(0, 50);
  const real = window.G, fields = Object.keys(snapshotG() || {});
  const out = { fields, noKey: [], presence: [], value: [], undeclared: [] };
  try {
    const base = JSON.parse(JSON.stringify(real));
    for (const f of fields) {
      const bare = { ...base }, dec = own(SNAP_DECLARED_EMPTY, f);
      delete bare[f];
      window.G = bare;
      const snapA = snapshotG();
      if (!own(snapA, f)) { out.noKey.push(f); continue; }
      const absent = snapA[f] === SNAP_ABSENT;
      if (!absent && !dec) out.undeclared.push(f + ' snapshots as ' + J(snapA[f]));
      bare[f] = { __snapRatchet: f };
      restoreG(snapA);
      const want = absent ? 'absent' : dec ? JSON.stringify(SNAP_DECLARED_EMPTY[f]) : null;
      const got = own(bare, f) ? JSON.stringify(bare[f]) : 'absent';
      if (want !== null && got !== want) out.presence.push(f + ': restored as ' + got.slice(0, 50) + ', wanted ' + want);
      if (!own(base, f)) continue;
      const owned = { ...base }, had = JSON.stringify(base[f]);
      window.G = owned;
      const snapB = snapshotG();
      owned[f] = { __snapRatchet: f };
      restoreG(snapB);
      if (JSON.stringify(owned[f]) !== had) out.value.push(f + ': owned value came back as ' + J(owned[f]) + ' instead of ' + had.slice(0, 50));
    }
  } finally { window.G = real; }
  return out;
};

/* nightWorld — ONE FIXTURE FOR THE RITUAL, NOT ONE PER TEST. Seventeen `G.x =`
   writes across the NIGHT- tests were one world stated seventeen times. Stated
   once, it ENDS THE WAY A BOOT ENDS — pushed through the REAL
   `applyRecord` (`stampRecordLikeLoad`'s shaped `hr_load` envelope), so the
   forecast reads `server` fields, not fail-closed UNKNOWN: a stubbed load is an
   ENVELOPE, not a seed. Stands the character up (`onFeet`) and COPIES the bag. */
export const nightWorld = (o) => {
  const G = window.G, w = o || {};
  G.activeMonster = w.foe || null;
  G.activeSkill = w.skill || null;
  G.skillTargetId = w.target || null;
  G.inventory = Object.assign({}, w.inventory || {});
  G.monsterHp = G.monsterMaxHp = 0;
  G.playerMaxHp = G.playerHp = 30;
  if (w.food) {
    G.foodSlot = w.food;
    G.traits = Object.assign({}, G.traits, { auto_eat: 1 });
    try { window.HearthriseAuto.setEat({ enabled: true, foodId: w.food }); } catch (e) {}
  }
  onFeet();
  try { stampRecordLikeLoad(G); } catch (e) {}
  /* AND THE BAG ARRIVES THE WAY A BOOT'S BAG ARRIVES. The ritual now
     refuses to speak before an envelope has STATED the bag (the strip used to
     price the fresh-G factory literal for the first ~10s of every reload), so
     a fixture that only assigned `G.inventory` would be describing a bag no
     server ever named. Pushed through the REAL door — `reconcileInventory`,
     the one apply both the idle-boot hr_load hydrate and applyEnvelopeState
     run — naming exactly the bag this world holds. */
  try {
    window.HearthriseAccrual.reconcileInventory(G, { ok: true, inventory: Object.assign({}, G.inventory) });
  } catch (e) {}
  return G;
};

/* ── b227 type-floor helpers (used by guards 19a-19e, far below) ──────────
   The floor. ONE constant: 19a-19d must never disagree about it. 19c/19d
   exist precisely because a token can be right while the screen is wrong,
   so they may not read the value off the token they are checking. */
export const TYPE_FLOOR = 14.5;

/* Files held by other agents during b227's parallel dispatch, so their
   font-sizes could not be swept in that commit. The exact declaration list
   (old -> new) is filed in .claude/coordination/HANDOFFS.md. Each entry is
   scoped to the region its file renders and was derived from a measured
   sweep (58 elements, no more). DELETE an entry when its file lands — an
   exemption that outlives its handoff is just a hole in the guard. */
const TYPE_PENDING_HANDOFF = [
  { file: 'src/features/home-dashboard.js', region: '#panel-profile [class*="hd-"]' },
  { file: 'src/features/world-events.js',   region: '#panel-events' },
  { file: 'src/features/companions.js',     region: '#panel-stable' },
  { file: 'src/styles/clan-seat.css',       region: '.clan-empty, .soc-signpost, .soc-signpost-txt' },
];
export const typeHandoffOwner = (el) => {
  for (const h of TYPE_PENDING_HANDOFF) {
    try { if (el.closest(h.region)) return h.file; } catch (e) { /* malformed selector */ }
  }
  return null;
};

/* Custom properties are now `calc(<n>px * var(--ui-scale, 1))`, so a token's
   computed value is a token stream, not a length — parseFloat() gives NaN.
   Measure them the only honest way: paint one and read what the engine did. */
export const typeTokenPx = (name) => {
  const probe = document.createElement('span');
  probe.style.cssText = 'position:absolute;left:-9999px;top:-9999px;visibility:hidden;font-size:var(' + name + ')';
  document.body.appendChild(probe);
  const px = parseFloat(getComputedStyle(probe).fontSize);
  probe.remove();
  return px;
};

/* The five sheets b227 swept. 19d holds ONLY these to the scalable form —
   a sheet the project does not own (or has not swept yet) is a handoff, not
   a test failure. */
export const TYPE_OWNED_SHEETS = /\/(legacy|art-direction|audit-overrides|theme-cozy|board-and-shop)\.css/;

/* THE RETREAT'S SHARED FIXTURE, written once (test-file ratchet TF-1: "if the
   setup is genuinely large, it is a helper, and a helper is written once").
   Each battery calls it and gets its OWN synthetic character - nothing is
   shared between the tests but the code that builds them. */
export const retreatFixture = () => {
    /* THE RETREAT (Recovery Rule rev. 3). "The realm does not keep swinging a
       fight it has proven the hero cannot win." On the 3rd CONSECUTIVE fall with
       an empty bag AT THE FALL - or the 6th whatever the bag held - the run
       ENDS; ANY kill resets the count. THE MEASURED NIGHT: max_hp 13, dark
       wizard, empty bag - 28 falls in one day, each charging the ladder's
       64-minute cap and face-down again inside a minute, about one kill an hour
       for ever, with no surface saying why. The AWAY half is
       tests/accrual-engine.mjs; this is the ATTENDED half and the two RENDERED
       surfaces. ⚠ NOTHING HERE TOUCHES `window.G` - the suite runs against a
       REAL SAVE, so this drives the engine on a synthetic state. */
    const C = window.HearthriseCore;
    const CS = C && C.combatSim;
    const AW = C && C.away;
    assert(CS && typeof CS.simulateTick === 'function' && typeof CS.forecastFight === 'function',
      'the combat-sim seam is missing — the Retreat cannot be exercised');
    assert(AW && typeof AW.retreatAtFall === 'function',
      'src/core/away.js does not export retreatAtFall — the rule has no table');

    const FOE = window.MONSTERS.dark_wizard ? 'dark_wizard' : 'slime';
    const FOOD = window.ITEMS && window.ITEMS.cooked_shrimp ? 'cooked_shrimp' : null;
    const MAXHP = 13;

    /* A SYNTHETIC CHARACTER, built field by field — never a clone of G. */
    const mkState = (inv) => ({
      activeMonster: FOE,
      playerHp: MAXHP, playerMaxHp: MAXHP,
      monsterHp: window.MONSTERS[FOE].hp, monsterMaxHp: window.MONSTERS[FOE].hp,
      stats: {}, inventory: inv || {}, skills: {},
      deathsTodayBefore: 0, deathsLifetimeBefore: 60,
      consecFalls: 0,
    });
    /* The LIVE ctx shape with an inert sink: no XP, no items, no toast.
       `fx.autoEat` is absent on purpose in the foodless fixtures - a character
       with an empty bag cannot eat, and stubbing one is a different character. */
    const mkCtx = (fx) => ({
      away: false, rng: C.rng, monsters: window.MONSTERS, items: window.ITEMS,
      bonus: () => 0, style: null,
      playerRolls: (m) => window.getPlayerCombatRolls(m, window.getEquipmentStats()),
      monsterRolls: (m) => window.getMonsterCombatRolls(m, window.getEquipmentStats()),
      weakness: (m) => window.getWeaknessInfo(m, window.getEquipmentStats()),
      botd: { killBonuses: () => ({ dropMult: 1, xpMult: 1 }) },
      fx: fx || {},
    });
    /* Drive the tick the way legacy.js `combatTick` does — swing, and on a fall
       stand back up at 40% against a full-HP foe, exactly as `hrCombatDown` /
       `hrStandUp` do. Returns every death `info` the run produced. */
    const runUntil = (st, ctx, maxFalls, maxTicks) => {
      const falls = [];
      let lastInfo = null;
      const sink = Object.assign({}, ctx.fx, {
        onDeath: (c, info) => { lastInfo = info; },
      });
      const c2 = Object.assign({}, ctx, { fx: sink });
      for (let i = 0; i < (maxTicks || 40000) && falls.length < maxFalls; i++) {
        const r = CS.simulateTick(st, c2);
        if (r.outcome === 'death') {
          falls.push(Object.assign({ retreat: !!r.retreat, foodless: !!r.foodless,
            consecFalls: r.consecFalls }, lastInfo || {}));
          if (r.retreat) break;
          st.monsterMaxHp = window.MONSTERS[st.activeMonster].hp;
          st.monsterHp = st.monsterMaxHp;
          st.playerHp = AW.resumeHpFor(st.playerMaxHp);
        }
        if (r.outcome === 'stop') break;
      }
      return falls;
    };
  /* THE AWAY-CARD READER, shared by the W5 batteries: the card's own pure
     seam flattened to text, and the one receipt every retreat render starts
     from. Built per call, so no test can see another's edits. */
        const H = window.HearthriseHome;
        const flat = (rec) => String(H.__awayCardHtml(rec))
          .replace(/<[^>]*>/g, ' ').replace(/&[a-z]+;/g, ' ').replace(/\s+/g, ' ');
        const BASE = {
          hrs: 12, awayMs: 12 * 3600000, gainedXp: 10, gainedItems: 0, gainedGold: 0,
          gainedKills: 0, crits: 0, featuredMs: 0, featuredDropMult: 1,
          capped: false, blessed: false, buffsPaused: false, rateMult: 1, at: Date.now(),
          died: true, diedTo: FOE, diedAfterMs: 8040000, deaths: 3,
          recoverMs: 360000, recoverRemainingMs: 0, recoverLadder: [0, 120000, 240000],
          stoppedBy: 'retreat', paidMs: 8040000,
          combat: { kills: 0, died: true, survivedMs: 8040000, diedTo: FOE, crits: 0 },
        };
  /* THE THREE RECEIPTS the W5 batteries read. Built here so each battery states
     only what it asserts; every call gets fresh objects. */
  const foodless = Object.assign({}, BASE,
    { retreatMs: 8040000, retreatFalls: 3, retreatFoodless: true });
  const fTxt = flat(foodless);
  const down = flat(Object.assign({}, foodless, { recoverRemainingMs: 47000 }));
  return { C, CS, AW, FOE, FOOD, MAXHP, mkState, mkCtx, runUntil, H, flat, BASE,
    foodless, fTxt, down };
};

/* THE RETREAT-RELOAD FIXTURE, written once (TF-1: "if the setup is genuinely
   large, it is a helper, and a helper is written once"). A reload after a
   Retreat arrives through TWO doors and only one of them was ever tested, so
   this drives both from one description of the server state: `settle(falls)` is
   the ATTENDED door (`applyEnvelopeState`, the `accrued:true` answer a reload
   with an unpriced window gets) and `boot(falls)` is the AWAY door (the
   `accrued:false` idle boot, through the real record.js path). `falls === null`
   omits `consec_falls` entirely — an older server, the case that must claim
   nothing. Both return the raised sheet's flattened text.
   ⚠ NOTHING HERE TOUCHES THE LIVE CHARACTER: `window.G` is swapped for a
     synthetic object and `done()` restores it with the pointer, the transport,
     the recovery line, the raise latch and the sheet — kept together because a
     test that keeps half of this teardown leaks a full-screen overlay into the
     next thirty tests. */
export const retreatReload = () => {
  const A = window.HearthriseAccrual;
  const D = window.HearthriseDeathSheet;
  const R = window.HearthriseRecord;
  const AW = window.HearthriseCore && window.HearthriseCore.away;
  assert(A && typeof A.applyEnvelopeState === 'function' && typeof A.clearFall === 'function',
    'the envelope seam is missing — the reload cannot be exercised');
  assert(R && typeof R.requestRecord === 'function', 'the boot record path is not wired');
  assert(D && typeof D.__resetForTest === 'function', 'the death-sheet seams are missing');
  assert(AW && typeof AW.RETREAT_FOODLESS_FALLS === 'number'
    && typeof AW.RETREAT_ANY_FALLS === 'number',
    'src/core/away.js does not export the Retreat table');

  const realFetch = window.fetch;
  const savedG = window.G;
  const savedPtr = { m: savedG.activeMonster, s: savedG.activeSkill,
    a: savedG.activeAction, r: savedG.activeArtisanRecipe };
  const wasOn = A.isServerAccrualEnabled();
  savedG.activeMonster = null; savedG.activeSkill = null;
  savedG.activeAction = null; savedG.activeArtisanRecipe = null;

  /* A FRESHLY BOOTED CLIENT: nothing known, no fight. That IS what a reload is
     — the fall moment went with the page, so every retreat fact below has to
     come off the envelope or not exist. */
  const freshG = () => (window.G = { inventory: {}, offlineBudget: {}, playerHp: 5,
    playerMaxHp: 13, activeMonster: null, skills: {}, stats: {}, combatLog: [] });
  /* THE SERVER STATE A RETREAT LEAVES BEHIND: pointer idled, recovery line 32
     minutes ahead (the ruling's own number, inside the 64-minute cap and far
     from any boundary a slow page could round to zero), 40% resume banked. */
  const stateFor = (falls, until) => {
    const st = { slot: 0, accrued_to: new Date().toISOString(), hp: 5, max_hp: 13,
      active_kind: 'idle', active_id: null,
      recovering_until: new Date(until).toISOString(), deaths_today: 3, deaths_lifetime: 63 };
    if (falls !== null) st.consec_falls = falls;
    return st;
  };
  const sheetText = (label) => {
    const el = document.getElementById('hr-death-scrim');
    assert(el && el.classList.contains('show'),
      label + ': the reload raised no sheet at all — no countdown, no Rest button, for 32 minutes '
      + 'in which nothing earns');
    return el.textContent || '';
  };
  const reset = () => {
    try { R.resetRecord(); R.configureRecord(null); } catch (e) {}
    try { D.__resetForTest(); } catch (e) {}
    try { A.clearFall(); } catch (e) {}
    /* The recovery line is SERVER-OWNED with no client setter (RECOVER-8 pins
       the absence of one), so it is retired the only sanctioned way. */
    try { A.applyEnvelopeState(window.G || {}, { state: { recovering_until: null } }); } catch (e) {}
    try { D.__resetForTest(); } catch (e) {}
  };
  const settle = (falls) => {
    reset(); A.setServerAccrualEnabled(true); freshG();
    A.applyEnvelopeState(window.G, { state: stateFor(falls, Date.now() + 32 * 60000) });
    return sheetText('settle(' + falls + ')');
  };
  const boot = async (falls) => {
    reset(); A.setServerAccrualEnabled(true);
    const st = stateFor(falls, Date.now() + 32 * 60000);
    window.fetch = function (u) {
      if (!/hr_load/.test(String(u))) return realFetch.apply(this, arguments);
      return Promise.resolve(new Response(JSON.stringify({ ok: true, version: 9,
        now: new Date().toISOString(), state: st, skills: {}, inventory: {} }), { status: 200 }));
    };
    freshG(); R.resetRecord();
    R.configureRecord({ url: 'https://proj.supabase.co/', apiKey: 'anon-key',
      authToken: () => 'jwt-token', slot: 0 });
    const v = await R.requestRecord();
    assert(v.outcome === 'loaded', 'boot(' + falls + '): the boot read did not load: '
      + JSON.stringify(v));
    return sheetText('boot(' + falls + ')');
  };
  const done = () => {
    window.fetch = realFetch;
    reset();
    window.G = savedG;
    savedG.activeMonster = savedPtr.m; savedG.activeSkill = savedPtr.s;
    savedG.activeAction = savedPtr.a; savedG.activeArtisanRecipe = savedPtr.r;
    try { A.setServerAccrualEnabled(wasOn); } catch (e) {}
    try { A.applyEnvelopeState(window.G || {}, { state: { recovering_until: null } }); } catch (e) {}
    try { D.__resetForTest(); } catch (e) {}
    try { window.refreshActivityBar(); } catch (e) {}
  };
  return { A, D, R, AW, settle, boot, done };
};

/* THE COMBAT-SCREEN FIXTURE, written once (test-file ratchet TF-1: "if the
   setup is genuinely large, it is a helper, and a helper is written once").
   Sixteen COMBAT-UI tests opened with the same four lines and closed with the
   same four; the save/restore pair is now ONE object, so a test that keeps half
   of the teardown - the leaked-overlay cascade, where one unclosed modal fails
   the next thirty tests thousands of lines away - cannot exist. */
export const combatScreen = () => {
  const CS = window.HearthriseCombatScreens;
  assert(CS, 'the two screens did not boot');
  const snap = snapshotG();
  const prevTab = window.activeTab;
  const restore = () => {
    try { window.stopCombat(); } catch (e) {}
    restoreG(snap);
    try { window.showTab(prevTab || 'profile'); } catch (e) {}
  };
  return { CS, G: window.G, restore };
};

/* ── THE AUTO-EAT MIRROR FIXTURE ──────────────────────────────────────
   The divergence the bug lived in, built once: a client on tier II (reconcileTraits
   once UNIONED the server's trait list and never removed, so a client tier could
   run AHEAD of it) holding a 50% preference, against the column
   hr_set_auto_eat clamped on write to Auto-Eat I's ceiling of 25.
   runSmokeTest parks the mirror so ~10 local-threshold fixtures stay honest on a
   signed-in page; these tests ARE it, so this unparks and restores — the contract
   SETTLE-5/6 and AUTOEAT-SYNC-1..3 have. */
/* The bank wire shape, once: hr_state_of states the enforced CAP and the rungs owned
   (one permanent `bank` row) in ONE body; and the pin goes back exactly as found. */
export const bankEnv = (cap, rung) => ({ ok: true, state: { bank_cap: cap }, progress_truncated: false,
  progress: [{ kind: 'unlock', key: 'bank', value: rung, period: '' }] });
export const restoreBankCap = (v) => { if (v === undefined) delete window.G._bankCap; else window.G._bankCap = v; };

/* EVERY TERM computeRenown() READS, EMPTIED — so the ratchet IS the score and a
   fixture's arithmetic is its own. Four fixtures kept their own copy of this
   block and each one had to be found again whenever a term was added; the
   server play-streak mirror (`_serverStreak`) was the term that proved it.
   Returns what it displaced so the caller can put it back. */
export const zeroRenownTerms = (G) => {
  const had = Object.prototype.hasOwnProperty.call(G, '_serverStreak');
  const before = { collection: G.collection, streak: G.streak, srv: had ? G._serverStreak : undefined, had };
  G.skills = {};
  G.stats = Object.assign({}, G.stats, { kills: 0 });
  G.bestiary = {}; G.quests = []; G.collection = {};
  G.streak = { best: 0, count: 0 };
  delete G._serverStreak;
  G.bountyHunter = Object.assign({}, G.bountyHunter || {}, { completed: 0 });
  return before;
};
export const restoreRenownTerms = (G, before) => {
  if (!before) return;
  G.collection = before.collection; G.streak = before.streak;
  if (before.had) G._serverStreak = before.srv; else delete G._serverStreak;
};

export const autoEatMirrorReady = () => {
  const A = window.HearthriseAuto, AC = window.HearthriseAccrual;
  return !!(A && AC && typeof AC.noteServerAutoEat === 'function'
    && typeof AC.__resetServerAutoEat === 'function'
    && typeof AC.serverAutoEatSettings === 'function');
};
export const autoEatMirrorFixture = (body) => {
  const G = window.G, A = window.HearthriseAuto, AC = window.HearthriseAccrual;
  const snap = snapshotG(), sT = G.traits, sS = G.settings, sP = G.autoEatPct;
  const sObs = AC.serverAutoEatSettings();
  let wasParked = false;
  try { wasParked = A._parkAutoEatMirror(false); } catch (e) {}
  try {
    G.traits = Object.assign({}, G.traits, { auto_eat: true, auto_eat_2: true });
    G.settings = Object.assign({}, G.settings || {});
    G.inventory = Object.assign({}, G.inventory, { cooked_shrimp: 20 });
    A.setEat({ enabled: true, foodId: 'cooked_shrimp', threshold: 0.5 });
    assert(Math.abs(A.getEat().threshold - 0.5) < 1e-9, 'fixture: the local preference must be 50%');
    AC.noteServerAutoEat({ state: { auto_eat_enabled: true, auto_eat_pct: 25 } });
    body(G, A, AC);
  } finally {
    const m = document.getElementById('settings-modal'); if (m) m.classList.remove('show');
    try { AC.__noteAutoEatSettings(sObs); } catch (e) {}
    try { A._parkAutoEatMirror(wasParked); } catch (e) {}
    G.traits = sT; G.settings = sS;
    if (sP === undefined) delete G.autoEatPct; else G.autoEatPct = sP;
    restoreG(snap);
  }
};

/* ══ THE HEARTHFIND BOARD FIXTURE (named pre-launch P2, 2026-09-13) ══════════
   Drive ONE board poll against a stubbed transport and hand back what crossed
   it. Two finds of one item: a LOUD finder is the control, without which
   "nobody was named" would pass for the wrong reason, and a NAMELESS one, which
   is what the server sends for a `presence_quiet` finder.
   The watermark is saved and restored - this must never leave a real player's
   chat dock permanently caught up. Chat.send is NOT stubbed: HF-5 already owns
   "the client can never SEND a hearthfind line", and a second copy of that
   assertion would be scaffolding nobody reads. */
const HF_BOARD = {
  ok: true, now: '2026-09-13T12:00:00Z', counts: { emberheart: 2 },
  rows: [
    { id: 900000001, name: 'LoudFinder', item_id: 'emberheart', source_kind: 'monster',
      source_id: 'dragon', one_in: 26000, found_at: '2026-09-13T11:00:00Z', nth: 1 },
    { id: 900000002, name: null, item_id: 'emberheart', source_kind: 'monster',
      source_id: 'dragon', one_in: 26000, found_at: '2026-09-13T11:30:00Z', nth: 2 },
  ],
};
export async function hfPoll() {
  const HF = window.HearthriseHearthfind;
  const o = { fetch: window.fetch, auth: window.HearthriseAuth,
    inject: window.Chat && window.Chat.inject };
  const mark = HF.__watermark(), out = { urls: [], injected: [], got: null };
  try {
    window.HearthriseAuth = Object.assign({}, o.auth, { getSession: () => ({ access_token: 'hf' }) });
    if (window.Chat) window.Chat.inject = (ch, m) => { out.injected.push([ch, m]); return true; };
    window.fetch = function (u, opts) {
      const url = String(u);
      if (url.indexOf('world_finds') === -1 && url.indexOf('display_names') === -1) return o.fetch.apply(this, arguments);
      out.urls.push(url + ' ' + ((opts && opts.method) || 'GET'));
      return Promise.resolve({ ok: true, status: 200, json: () => Promise.resolve(HF_BOARD) });
    };
    HF.__resetProbe(); HF.__setWatermark(900000000);   // both rows "fresh", nothing swallowed
    out.got = await HF.refreshBoard();
  } finally {
    window.fetch = o.fetch; window.HearthriseAuth = o.auth;
    if (window.Chat && o.inject) window.Chat.inject = o.inject;
    HF.__setWatermark(mark); HF.__resetProbe();
  }
  return out;
}

/* THE CHARM TESTS' ONE FIXTURE AND ONE DRIVER (CHARM-2, CHARM-3).
   Written once, on the test-file ratchet's own terms: two tests that each rebuilt
   the roster search and the envelope driver cost twice the scaffolding and gave
   one of them a chance to drift into testing something subtly different.
   `hrCharmFixture` finds a REAL monster whose class is nameable and whose table
   has a ROLLABLE row — a guaranteed row (ch >= 1) is untouched by design, so it
   would make every rate assertion vacuous. `hrCharmDriver` answers the accrual
   funnel with the idle envelope a reloading player actually gets, which is the
   only response the charm mirror rides. */
export function hrCharmFixture() {
  const C = window.HearthriseCharms; const M = window.MONSTERS || {};
  const id = Object.keys(M).find((k) => C && C.classOfMonsterId(k)
    && Array.isArray(M[k].drops) && M[k].drops.some((d) => d.ch > 0 && d.ch < 1));
  return { id: id || null, cls: id ? C.classOfMonsterId(id) : null, m: id ? M[id] : null };
}

export function hrCharmDriver() {
  const A = window.HearthriseAccrual; const realFetch = window.fetch;
  return {
    async drive(bestiary) {
      const env = { ok: true, accrued: false, reason: 'idle', version: 5,
        now: new Date().toISOString(), ...(bestiary ? { bestiary } : {}) };
      window.fetch = (u, init) => (/hr-accrue/.test(String(u))
        ? Promise.resolve(new Response(JSON.stringify(env), { status: 200 }))
        : realFetch.call(window, u, init));
      A.resetAccrualGate();
      A.configureAccrual({ url: 'https://proj.supabase.co', apiKey: 'anon-key', authToken: () => 'jwt-token', slot: 0 });
      return A.requestAccrual({ force: true });
    },
    restore() {
      window.fetch = realFetch;
      try { A.resetAccrualGate(); A.configureAccrual(null); } catch (e) {}
    },
  };
}


/* Re-exported for the domain modules: one seam, not four. */
